use adamantium::Actor;

struct Account {
    balance: u64,
    version: u64,
}

async fn withdraw(account: &Actor<Account>, amount: u64) -> Result<(), &'static str> {
    let balance = account.read(|a| a.balance);
    if balance < amount {
        return Err("insufficient funds");
    }
    authorize_payout(amount).await?;
    account.with(|a| {
        a.balance = a.balance.saturating_sub(amount);
        a.version += 1;
    });
    Ok(())
}

use adamantium::Actor;

struct Account {
    balance: u64,
    version: u64,
}

async fn withdraw(account: &Actor<Account>, amount: u64) -> Result<(), &'static str> {
    let (balance, version) = account.read(|a| (a.balance, a.version));
    if balance < amount {
        return Err("insufficient funds");
    }
    authorize_payout(amount).await?;
    account.with(|a| {
        if a.version != version || a.balance < amount {
            return Err("account changed during authorization");
        }
        a.balance -= amount;
        a.version += 1;
        Ok(())
    })
}

use std::sync::Arc;
use tokio::sync::Mutex;

async fn record_delivery(state: Arc<Mutex<u64>>, payload: &[u8]) -> Result<u64, &'static str> {
    let mut sent = state.lock().await;
    let next = *sent + 1;
    deliver_webhook(next, payload).await?;
    *sent = next;
    Ok(next)
}

