use adamantium::Actor;

struct Metrics {
    in_flight: usize,
}

async fn handle_upload(metrics: &Actor<Metrics>, data: &[u8]) -> Result<(), UploadError> {
    metrics.with(|m| m.in_flight += 1);
    let result = send_to_storage(data).await;
    metrics.with(|m| m.in_flight -= 1);
    result
}

use adamantium::Actor;

struct Metrics {
    in_flight: usize,
}

struct InFlightGuard {
    metrics: Actor<Metrics>,
}

impl Drop for InFlightGuard {
    fn drop(&mut self) {
        self.metrics.with(|m| m.in_flight = m.in_flight.saturating_sub(1));
    }
}

async fn handle_upload(metrics: &Actor<Metrics>, data: &[u8]) -> Result<(), UploadError> {
    metrics.with(|m| m.in_flight += 1);
    let _guard = InFlightGuard { metrics: metrics.clone() };
    send_to_storage(data).await
}

