use adamantium::{Actor, Map};

struct Bank {
    balances: Actor<Map<u64, u64>>,
    total_supply: Actor<u64>,
}

impl Bank {
    fn deposit(&self, user: u64, amount: u64) {
        self.balances.with(|m| {
            let current = m.get(&user).copied().unwrap_or(0);
            m.insert(user, current + amount);
        });
        self.total_supply.with(|total| *total += amount);
    }

    fn audit_matches(&self) -> bool {
        let sum: u64 = self.balances.read(|m| m.values().copied().sum());
        let total = self.total_supply.read(|t| *t);
        sum == total
    }
}

use adamantium::{Actor, Map};

struct BankState {
    balances: Map<u64, u64>,
    total_supply: u64,
}

struct Bank {
    state: Actor<BankState>,
}

impl Bank {
    fn deposit(&self, user: u64, amount: u64) {
        self.state.with(|s| {
            let current = s.balances.get(&user).copied().unwrap_or(0);
            s.balances.insert(user, current + amount);
            s.total_supply += amount;
        });
    }

    fn audit_matches(&self) -> bool {
        self.state.read(|s| {
            let sum: u64 = s.balances.values().copied().sum();
            sum == s.total_supply
        })
    }
}

