use std::collections::{HashMap, VecDeque};
use adamantium::Actor;

struct CacheInner {
    entries: HashMap<u64, String>,
    order: VecDeque<u64>,
}

struct ProfileCache {
    inner: Actor<CacheInner>,
    max_entries: usize,
}

impl ProfileCache {
    fn get(&self, user_id: u64) -> Option<String> {
        self.inner.read(|c| c.entries.get(&user_id).cloned())
    }

    fn put(&self, user_id: u64, name: String) {
        self.inner.with(|c| {
            if !c.entries.contains_key(&user_id) {
                if c.entries.len() >= self.max_entries {
                    if let Some(oldest) = c.order.pop_front() {
                        c.entries.remove(&oldest);
                    }
                }
                c.order.push_back(user_id);
            }
            c.entries.insert(user_id, name);
        });
    }
}

