impl TenantQuota {
    async fn submit_job(&self, cost: u64, payload: &[u8]) -> Result<(), QuotaError> {
        self.state.with(|q| {
            if q.used.saturating_add(cost) > q.limit {
                return Err(QuotaError::Exceeded);
            }
            q.used += cost;
            Ok(())
        })?;
        enqueue_remote(payload).await
    }
}

use adamantium::{Str, Watch};

#[derive(Clone)]
struct RouteTable {
    primary: Str,
    secondary: Str,
    timeout_ms: u64,
}

async fn check_and_failover(routing: &Watch<RouteTable>) {
    let current = routing.get();
    if !probe_healthy(&current.primary).await {
        let next = RouteTable {
            primary: current.secondary,
            secondary: current.primary,
            timeout_ms: current.timeout_ms,
        };
        routing.send(next);
    }
}

use adamantium::{Actor, Str, Watch};

#[derive(Clone)]
struct RouteTable {
    epoch: u64,
    primary: Str,
    secondary: Str,
    timeout_ms: u64,
}

async fn check_and_failover(state: &Actor<RouteTable>, routing: &Watch<RouteTable>) {
    let (epoch, primary) = state.read(|r| (r.epoch, r.primary.clone()));
    if !probe_healthy(&primary).await {
        let updated = state.with(|r| {
            if r.epoch != epoch {
                return None;
            }
            std::mem::swap(&mut r.primary, &mut r.secondary);
            r.epoch += 1;
            Some(r.clone())
        });
        if let Some(table) = updated {
            routing.send(table);
        }
    }
}

use std::collections::HashMap;
use adamantium::{Actor, Bytes, Str};

struct CacheState {
    entries: HashMap<Str, (u64, Bytes)>,
    version: u64,
}

struct KeyValueCache {
    state: Actor<CacheState>,
}

impl KeyValueCache {
    fn put(&self, key: Str, value: Bytes) {
        self.state.with(|s| {
            s.version += 1;
            let ver = s.version;
            s.entries.insert(key, (ver, value));
        });
    }

    async fn get_or_load(&self, key: Str) -> Result<Bytes, DbError> {
        if let Some((_, val)) = self.state.read(|s| s.entries.get(&key).cloned()) {
            return Ok(val);
        }
        let loaded = load_from_db(&key).await?;
        self.state.with(|s| {
            s.version += 1;
            let ver = s.version;
            s.entries.insert(key, (ver, loaded.clone()));
        });
        Ok(loaded)
    }
}

use std::collections::HashMap;
use adamantium::{Actor, Bytes, Str};

struct CacheState {
    entries: HashMap<Str, (u64, Bytes)>,
    version: u64,
}

struct KeyValueCache {
    state: Actor<CacheState>,
}

impl KeyValueCache {
    fn put(&self, key: Str, value: Bytes) {
        self.state.with(|s| {
            s.version += 1;
            let ver = s.version;
            s.entries.insert(key, (ver, value));
        });
    }

    async fn get_or_load(&self, key: Str) -> Result<Bytes, DbError> {
        let observed = self.state.read(|s| {
            (s.version, s.entries.get(&key).map(|(_, v)| v.clone()))
        });
        if let Some(val) = observed.1 {
            return Ok(val);
        }
        let loaded = load_from_db(&key).await?;
        let result = self.state.with(|s| {
            if s.version == observed.0 {
                s.version += 1;
                let ver = s.version;
                s.entries.insert(key, (ver, loaded.clone()));
                loaded
            } else if let Some((_, newer)) = s.entries.get(&key) {
                newer.clone()
            } else {
                loaded
            }
        });
        Ok(result)
    }
}

use std::sync::atomic::{AtomicU64, Ordering};

struct WalWriter {
    next_seq: AtomicU64,
}

impl WalWriter {
    async fn append_record(&self, body: &[u8]) -> Result<u64, IoError> {
        let seq = self.next_seq.load(Ordering::Acquire);
        write_remote_log(seq, body).await?;
        self.next_seq.store(seq + 1, Ordering::Release);
        Ok(seq)
    }
}

