}

async fn send_frame(state: &Actor<ConnState>, body: Bytes) -> Result<u32, IoError> {
    let id = state.read(|c| c.next_frame_id);
    transmit_frame(id, &body).await?;
    state.with(|c| c.next_frame_id = id + 1);
    Ok(id)
}

use adamantium::{AsyncActor, Bytes, Reply, Tasks};

#[derive(Default)]
struct ConnState {
    next_frame_id: u32,
}

struct FrameMsg {
    body: Bytes,
    reply: Reply<u32>,
}

fn start_framer(tasks: &mut Tasks<IoError>) -> AsyncActor<FrameMsg> {
    AsyncActor::new(tasks, ConnState::default(), 16, |state, msg: FrameMsg| {
        Box::pin(async move {
            let id = state.next_frame_id;
            transmit_frame(id, &msg.body).await?;
            state.next_frame_id = id + 1;
            let _ = msg.reply.send(id);
            Ok(())
        })
    })
}

use std::sync::{Arc, Mutex};

async fn apply_adjustment(counter: Arc<Mutex<i64>>, key: &str) -> Result<i64, ApiError> {
    let before = {
        let guard = counter.lock().map_err(|_| ApiError::Poisoned)?;
        *guard
    };
    let delta = fetch_adjustment(key, before).await?;
    let updated = before + delta;
    let mut guard = counter.lock().map_err(|_| ApiError::Poisoned)?;
    *guard = updated;
    Ok(updated)
}

use std::cell::Cell;
use std::sync::atomic::{AtomicU32, Ordering};

static NEXT_SHARD: AtomicU32 = AtomicU32::new(1);

thread_local! {
    static WORKER_SHARD: Cell<u32> = Cell::new(NEXT_SHARD.fetch_add(1, Ordering::Relaxed));
}

async fn write_sharded(record: &[u8]) -> Result<(), IoError> {
    let shard = WORKER_SHARD.with(Cell::get);
    let encoded = compress_async(record).await?;
    store_to_shard(shard, &encoded).await?;
    WORKER_SHARD.with(|c| c.set(shard + 1));
    Ok(())
}

use std::sync::Arc;
use tokio::sync::Mutex;

struct Cursor {
    offset: u64,
}

async fn advance(cursor: Arc<Mutex<Cursor>>, batch: &[u8]) -> Result<u64, IoError> {
    let mut guard = cursor.lock().await;
    let target = guard.offset + batch.len() as u64;
    flush_chunk(guard.offset, batch).await?;
    guard.offset = target;
    Ok(target)
}

