use std::collections::HashMap;
use adamantium::Actor;

#[derive(Clone, Copy, PartialEq, Eq)]
enum Status { Pending, Running, Done }

async fn run_job(jobs: &Actor<HashMap<u64, Status>>, id: u64) -> Result<(), JobError> {
    jobs.with(|m| {
        m.insert(id, Status::Running);
    });
    execute_remote_job(id).await?;
    jobs.with(|m| {
        m.insert(id, Status::Done);
    });
    Ok(())
}

use std::collections::HashMap;
use adamantium::Actor;

#[derive(Clone, Copy, PartialEq, Eq)]
enum Status { Pending, Running, Done }

struct RunningGuard {
    jobs: Actor<HashMap<u64, Status>>,
    id: u64,
    finished: bool,
}

impl Drop for RunningGuard {
    fn drop(&mut self) {
        if !self.finished {
            self.jobs.with(|m| {
                m.insert(self.id, Status::Pending);
            });
        }
    }
}

async fn run_job(jobs: &Actor<HashMap<u64, Status>>, id: u64) -> Result<(), JobError> {
    jobs.with(|m| {
        m.insert(id, Status::Running);
    });
    let mut guard = RunningGuard { jobs: jobs.clone(), id, finished: false };
    execute_remote_job(id).await?;
    jobs.with(|m| {
        m.insert(id, Status::Done);
    });
    guard.finished = true;
    Ok(())
}

use adamantium::Actor;

struct Inventory {
    available: u32,
}

async fn checkout(inv: &Actor<Inventory>, qty: u32, order_id: u64) -> Result<(), CheckoutError> {
    inv.with(|i| {
        if i.available < qty {
            return Err(CheckoutError::OutOfStock);
        }
        i.available -= qty;
        Ok(())
    })?;
    if let Err(err) = charge_payment(order_id, qty).await {
        inv.with(|i| i.available += qty);
        return Err(err);
    }
    Ok(())
}

use adamantium::Actor;

struct Inventory {
    available: u32,
}

struct StockHold {
    inv: Actor<Inventory>,
    qty: u32,
    committed: bool,
}

impl Drop for StockHold {
    fn drop(&mut self) {
        if !self.committed {
            self.inv.with(|i| i.available += self.qty);
        }
    }
}

async fn checkout(inv: &Actor<Inventory>, qty: u32, order_id: u64) -> Result<(), CheckoutError> {
    inv.with(|i| {
        if i.available < qty {
            return Err(CheckoutError::OutOfStock);
        }
        i.available -= qty;
        Ok(())
    })?;
    let mut hold = StockHold { inv: inv.clone(), qty, committed: false };
    charge_payment(order_id, qty).await?;
    hold.committed = true;
    Ok(())
}

use std::collections::HashSet;
use adamantium::Actor;

async fn upload_for_user(active: &Actor<HashSet<u64>>, user_id: u64, data: &[u8]) -> Result<(), UploadError> {
    let entered = active.with(|set| set.insert(user_id));
    if !entered {
        return Err(UploadError::Busy);
    }
    let outcome = write_blob(user_id, data).await;
    active.with(|set| {
        set.remove(&user_id);
    });
    outcome
}

use adamantium::KeyedLimit;

async fn upload_for_user(uploads: &KeyedLimit<u64>, user_id: u64, data: &[u8]) -> Result<(), UploadError> {
    uploads.run(user_id, || write_blob(user_id, data)).await
}

use adamantium::{Actor, Map};

async fn transfer(
    balances: &Actor<Map<u64, u64>>,
    from: u64,
    to: u64,
    amount: u64,
) -> Result<(), TransferError> {
    balances.with(|m| {
        let current = m.get(&from).copied().unwrap_or(0);
        if current < amount {
            return Err(TransferError::Insufficient);
        }
        m.insert(from, current - amount);
        Ok(())
    })?;
    notify_clearinghouse(from, to, amount).await?;
    balances.with(|m| {
        let current = m.get(&to).copied().unwrap_or(0);
        m.insert(to, current + amount);
    });
    Ok(())
}

use adamantium::{Actor, Map};

async fn transfer(
    balances: &Actor<Map<u64, u64>>,
    from: u64,
    to: u64,
    amount: u64,
) -> Result<(), TransferError> {
    notify_clearinghouse(from, to, amount).await?;
    balances.with(|m| {
        let src = m.get(&from).copied().unwrap_or(0);
        if src < amount {
            return Err(TransferError::Insufficient);
        }
        let dst = m.get(&to).copied().unwrap_or(0);
        m.insert(from, src - amount);
        m.insert(to, dst + amount);
        Ok(())
    })
}

use std::collections::VecDeque;
