    Ok(true)
}

use std::collections::VecDeque;
use adamantium::{Actor, Sender};

async fn forward_one(outbox: &Actor<VecDeque<String>>, tx: &Sender<String>) -> Result<bool, &'static str> {
    let Some(msg) = outbox.read(|q| q.front().cloned()) else {
        return Ok(false);
    };
    tx.send(msg).await.map_err(|_| "closed")?;
    outbox.with(VecDeque::pop_front);
    Ok(true)
}

use adamantium::{Actor, AsyncActor, Bytes, Tasks};

struct ProtocolMetrics {
    pending_bytes: usize,
    in_flight_ids: Vec<u64>,
    flushed: u64,
}

struct FrameMsg {
    id: u64,
    payload: Bytes,
}

fn spawn_writer(tasks: &mut Tasks<IoError>, metrics: Actor<ProtocolMetrics>) -> AsyncActor<FrameMsg> {
    AsyncActor::new(tasks, (), 8, move |_, msg: FrameMsg| {
        let metrics = metrics.clone();
        Box::pin(async move {
            let len = msg.payload.len();
            metrics.with(|m| {
                m.pending_bytes += len;
                m.in_flight_ids.push(msg.id);
            });
            flush_frame(msg.id, &msg.payload).await?;
            metrics.with(|m| {
                m.in_flight_ids.retain(|&id| id != msg.id);
                m.pending_bytes -= len;
                m.flushed += 1;
            });
            Ok(())
        })
    })
}

use adamantium::{Actor, AsyncActor, Bytes, Tasks};

struct ProtocolMetrics {
    flushed_bytes: usize,
    flushed: u64,
}

struct FrameMsg {
    id: u64,
    payload: Bytes,
}

fn spawn_writer(tasks: &mut Tasks<IoError>, metrics: Actor<ProtocolMetrics>) -> AsyncActor<FrameMsg> {
    AsyncActor::new(tasks, (), 8, move |_, msg: FrameMsg| {
        let metrics = metrics.clone();
        Box::pin(async move {
            let len = msg.payload.len();
            flush_frame(msg.id, &msg.payload).await?;
            metrics.with(|m| {
                m.flushed_bytes += len;
                m.flushed += 1;
            });
            Ok(())
        })
    })
}

use std::sync::atomic::{AtomicBool, Ordering};

struct Replicator {
    syncing: AtomicBool,
}

impl Replicator {
    async fn sync_now(&self) -> Result<(), SyncError> {
        if self.syncing.swap(true, Ordering::AcqRel) {
            return Ok(());
        }
        let res = pull_remote_deltas().await;
        self.syncing.store(false, Ordering::Release);
        res
    }
}

use std::sync::atomic::{AtomicBool, Ordering};

struct Replicator {
    syncing: AtomicBool,
}

struct ClearOnDrop<'a>(&'a AtomicBool);

impl Drop for ClearOnDrop<'_> {
    fn drop(&mut self) {
        self.0.store(false, Ordering::Release);
    }
}

impl Replicator {
    async fn sync_now(&self) -> Result<(), SyncError> {
        if self.syncing.swap(true, Ordering::AcqRel) {
            return Ok(());
        }
        let _guard = ClearOnDrop(&self.syncing);
        pull_remote_deltas().await
    }
}

use adamantium::Actor;

struct PoolState {
    idle: Vec<Conn>,
    checked_out: usize,
}

async fn probe_idle(pool: &Actor<PoolState>) -> Result<(), ProbeError> {
    let Some(conn) = pool.with(|p| {
        let c = p.idle.pop()?;
        p.checked_out += 1;
        Some(c)
    }) else {
        return Ok(());
    };
    ping_conn(&conn).await?;
    pool.with(|p| {
        p.checked_out -= 1;
        p.idle.push(conn);
    });
    Ok(())
}

