}

async fn commit_with_deadline(state: &Actor<TxState>, tx_id: u64) -> Result<(), &'static str> {
    race((
        async {
            time::sleep(Duration::from_secs(1)).await;
            Err("deadline")
        },
        async {
            state.with(|s| s.active_tx = Some(tx_id));
            send_commit(tx_id).await.map_err(|_| "io")?;
            state.with(|s| s.active_tx = None);
            Ok(())
        },
    ))
    .await
}

