use adamantium::Actor;

struct Account {
    balance: u64,
}

fn transfer(from: &Actor<Account>, to: &Actor<Account>, amount: u64) -> Result<(), &'static str> {
    from.with(|a| {
        if a.balance < amount {
            return Err("insufficient");
        }
        a.balance -= amount;
        Ok(())
    })?;
    to.with(|b| b.balance += amount);
    Ok(())
}

fn total_balance(a: &Actor<Account>, b: &Actor<Account>) -> u64 {
    a.read(|x| x.balance) + b.read(|y| y.balance)
}

use adamantium::{Actor, Map};

struct Ledger {
    accounts: Actor<Map<u64, u64>>,
}

impl Ledger {
    fn transfer(&self, from: u64, to: u64, amount: u64) -> Result<(), &'static str> {
        self.accounts.with(|m| {
            let src = m.get(&from).copied().unwrap_or(0);
            if src < amount {
                return Err("insufficient");
            }
            let dst = m.get(&to).copied().unwrap_or(0);
            m.insert(from, src - amount);
            m.insert(to, dst + amount);
            Ok(())
        })
    }

    fn total_balance(&self) -> u64 {
        self.accounts.read(|m| m.values().copied().sum())
    }
}

use std::collections::{HashMap, VecDeque};
use adamantium::{Actor, Bytes, Str};

struct Cache {
    entries: Actor<HashMap<Str, Bytes>>,
    order: Actor<VecDeque<Str>>,
    cap: usize,
}

impl Cache {
    fn insert(&self, key: Str, value: Bytes) {
        let evicted = self.order.with(|q| {
            q.push_back(key.clone());
            if q.len() > self.cap { q.pop_front() } else { None }
        });
        self.entries.with(|m| {
            if let Some(old) = evicted {
                m.remove(&old);
            }
            m.insert(key, value);
        });
    }
}

use std::collections::{HashMap, VecDeque};
use adamantium::{Actor, Bytes, Str};

struct CacheInner {
    entries: HashMap<Str, Bytes>,
    order: VecDeque<Str>,
}

struct Cache {
    inner: Actor<CacheInner>,
    cap: usize,
}

impl Cache {
    fn insert(&self, key: Str, value: Bytes) {
        self.inner.with(|c| {
            c.order.push_back(key.clone());
            if c.order.len() > self.cap {
                if let Some(old) = c.order.pop_front() {
                    c.entries.remove(&old);
                }
            }
            c.entries.insert(key, value);
        });
    }
}

use std::collections::VecDeque;
use std::sync::Arc;
use std::sync::atomic::{AtomicUsize, Ordering};
use adamantium::Actor;

struct WorkQueue {
    items: Actor<VecDeque<u64>>,
    len: Arc<AtomicUsize>,
}

impl WorkQueue {
    fn push(&self, job: u64) {
        self.items.with(|q| q.push_back(job));
        self.len.fetch_add(1, Ordering::Release);
    }

    fn pop(&self) -> Option<u64> {
        if self.len.load(Ordering::Acquire) == 0 {
            return None;
        }
        let item = self.items.with(VecDeque::pop_front);
        if item.is_some() {
            self.len.fetch_sub(1, Ordering::Release);
        }
        item
    }
}

use std::collections::VecDeque;
use adamantium::Actor;

struct WorkQueue {
