use std::collections::{HashMap, HashSet};
use adamantium::Actor;

struct LeaseTable {
    active: Actor<HashSet<u64>>,
    owners: Actor<HashMap<u64, u32>>,
}

impl LeaseTable {
    fn acquire(&self, key: u64, worker: u32) -> bool {
        if !self.active.with(|s| s.insert(key)) {
            return false;
        }
        self.owners.with(|m| {
            m.insert(key, worker);
        });
        true
    }

    fn release(&self, key: u64, worker: u32) {
        let is_owner = self.owners.read(|m| m.get(&key) == Some(&worker));
        if is_owner {
            self.owners.with(|m| m.remove(&key));
            self.active.with(|s| s.remove(&key));
        }
    }
}

use std::collections::HashMap;
use adamantium::Actor;

struct LeaseTable {
    owners: Actor<HashMap<u64, u32>>,
}

impl LeaseTable {
    fn acquire(&self, key: u64, worker: u32) -> bool {
        self.owners.with(|m| {
            if m.contains_key(&key) {
                return false;
            }
            m.insert(key, worker);
            true
        })
    }

    fn release(&self, key: u64, worker: u32) {
        self.owners.with(|m| {
            if m.get(&key) == Some(&worker) {
                m.remove(&key);
            }
        });
    }
}

use adamantium::{Actor, Array, Str};

struct PolicyStore {
    epoch: Actor<u64>,
    rules: Actor<Array<Str>>,
}

impl PolicyStore {
    fn replace(&self, next: Array<Str>) {
        self.epoch.with(|e| *e += 1);
        self.rules.with(|r| *r = next);
    }

    fn snapshot(&self) -> (u64, Array<Str>) {
        let epoch = self.epoch.read(|e| *e);
        let rules = self.rules.snapshot();
        (epoch, rules)
    }
}

