        self.state.read(|s| (s.epoch, s.rules.clone()))
    }
}

use adamantium::Actor;

struct Pool {
    idle: Actor<Vec<u64>>,
    in_use: Actor<usize>,
    max_conns: usize,
}

impl Pool {
    fn acquire(&self) -> Option<u64> {
        if self.in_use.read(|n| *n) >= self.max_conns {
            return None;
        }
        let conn = self.idle.with(Vec::pop).unwrap_or_else(open_new_conn);
        self.in_use.with(|n| *n += 1);
        Some(conn)
    }

    fn release(&self, conn: u64) {
        self.idle.with(|v| v.push(conn));
        self.in_use.with(|n| *n -= 1);
    }
}

