use std::collections::HashMap;
use std::sync::{Arc, Mutex};

struct Warehouse {
    available: Arc<Mutex<HashMap<u64, u32>>>,
    reserved: Arc<Mutex<HashMap<u64, u32>>>,
}

impl Warehouse {
    fn reserve(&self, sku: u64, qty: u32) -> bool {
        let ok = {
            let mut avail = self.available.lock().unwrap();
            match avail.get_mut(&sku) {
                Some(count) if *count >= qty => { *count -= qty; true }
                _ => false,
            }
        };
        if !ok {
            return false;
        }
        let mut res = self.reserved.lock().unwrap();
        *res.entry(sku).or_insert(0) += qty;
        true
    }
}

