fn finish_ticket_async(pending: Actor<Vec<u64>>, completed: Actor<Vec<u64>>, id: u64) {
    tokio::spawn(async move {
        let removed = pending.with(|list| {
            if let Some(pos) = list.iter().position(|&x| x == id) {
                list.remove(pos);
                true
            } else {
                false
            }
        });
        if removed {
            completed.with(|done| done.push(id));
        }
    });
}

