use std::collections::{HashSet, VecDeque};
use adamantium::{Actor, Str};

struct DedupState {
    seen: HashSet<Str>,
    order: VecDeque<Str>,
}

struct Deduplicator {
    state: Actor<DedupState>,
    max_ids: usize,
}

impl Deduplicator {
    fn is_new(&self, message_id: Str) -> bool {
        self.state.with(|s| {
            if !s.seen.insert(message_id.clone()) {
                return false;
            }
            s.order.push_back(message_id);
            if s.order.len() > self.max_ids {
                if let Some(oldest) = s.order.pop_front() {
                    s.seen.remove(&oldest);
                }
            }
            true
        })
    }
}

