#[derive(Clone, Copy)]
struct Bucket {
    tokens: u32,
    last_sec: u64,
}

struct IpLimiter {
    buckets: Actor<Map<IpAddr, Bucket>>,
}

impl IpLimiter {
    fn allow(&self, ip: IpAddr, now_sec: u64) -> bool {
        self.buckets.with(|m| {
            let mut b = m.get(&ip).copied().unwrap_or(Bucket { tokens: 10, last_sec: now_sec });
            if now_sec > b.last_sec {
                b.tokens = 10;
                b.last_sec = now_sec;
            }
            let ok = b.tokens > 0;
            if ok { b.tokens -= 1; }
            m.insert(ip, b);
            ok
        })
    }
}

use std::collections::HashMap;
use std::net::IpAddr;
use adamantium::Actor;

const MAX_IPS: usize = 10_000;
const IDLE_TTL_SECS: u64 = 300;

#[derive(Clone, Copy)]
struct Bucket {
    tokens: u32,
    last_sec: u64,
}

struct IpLimiter {
    buckets: Actor<HashMap<IpAddr, Bucket>>,
}

impl IpLimiter {
    fn allow(&self, ip: IpAddr, now_sec: u64) -> bool {
        self.buckets.with(|m| {
            if !m.contains_key(&ip) && m.len() >= MAX_IPS {
                m.retain(|_, b| now_sec.saturating_sub(b.last_sec) < IDLE_TTL_SECS);
                if m.len() >= MAX_IPS {
                    return false;
                }
            }
            let b = m.entry(ip).or_insert(Bucket { tokens: 10, last_sec: now_sec });
            if now_sec > b.last_sec {
                b.tokens = 10;
                b.last_sec = now_sec;
            }
            if b.tokens == 0 {
                return false;
            }
            b.tokens -= 1;
            true
        })
    }
}

use std::collections::HashMap;
use std::net::SocketAddr;
use std::time::Instant;
use adamantium::{Actor, Cancellation, Tasks};

async fn accept_loop(
    listener: &TcpListener,
    cancel: Cancellation,
    connected: Actor<HashMap<u64, (SocketAddr, Instant)>>,
) -> Result<(), std::io::Error> {
    let mut next_id = 0u64;
    let _ = Tasks::run_until(cancel, None, async |tasks| {
        loop {
            let (stream, peer) = listener.accept().await?;
            next_id += 1;
            let id = next_id;
            connected.with(|m| {
                m.insert(id, (peer, Instant::now()));
            });
            tasks.spawn_handled(serve(stream), |_| {});
        }
    })
    .await;
    Ok(())
}

use std::collections::HashMap;
use std::net::SocketAddr;
use std::time::Instant;
use adamantium::{Actor, Cancellation, Limit, Tasks};

struct ConnGuard {
    connected: Actor<HashMap<u64, (SocketAddr, Instant)>>,
    id: u64,
}

impl Drop for ConnGuard {
    fn drop(&mut self) {
        self.connected.with(|m| {
            m.remove(&self.id);
        });
    }
}

async fn accept_loop(
    listener: &TcpListener,
    cancel: Cancellation,
    connected: Actor<HashMap<u64, (SocketAddr, Instant)>>,
) -> Result<(), std::io::Error> {
    let limit = Limit::new(256);
    let mut next_id = 0u64;
    let _ = Tasks::run_until(cancel, None, async |tasks| {
        loop {
            let (stream, peer) = listener.accept().await?;
            next_id += 1;
            let id = next_id;
            let conn_map = connected.clone();
            let gate = limit.clone();
            tasks.spawn_handled(
                async move {
                    gate.run(|| async move {
                        conn_map.with(|m| {
                            m.insert(id, (peer, Instant::now()));
                        });
                        let _guard = ConnGuard { connected: conn_map, id };
                        serve(stream).await
                    })
                    .await
                },
                |_| {},
            );
        }
    })
    .await;
    Ok(())
}

