}

struct BudgetState {
    used_credits: u64,
    dispatched_jobs: u64,
    rejected_jobs: u64,
    audit_ring: VecDeque<AuditEntry>,
}

impl BudgetState {
    fn new(max_audit: usize) -> Self {
        Self {
            used_credits: 0,
            dispatched_jobs: 0,
            rejected_jobs: 0,
            audit_ring: VecDeque::with_capacity(max_audit.min(128)),
        }
    }

    fn record_audit(&mut self, entry: AuditEntry, cap: usize) {
        if cap == 0 {
            return;
        }
        while self.audit_ring.len() >= cap {
            self.audit_ring.pop_front();
        }
        self.audit_ring.push_back(entry);
    }
}

pub struct TenantBudgetService {
    config: BudgetConfig,
    state: Actor<BudgetState>,
}

impl TenantBudgetService {
    pub fn new(config: BudgetConfig) -> Self {
        let cap = config.max_audit_entries;
        Self {
            config,
            state: Actor::new(BudgetState::new(cap)),
        }
    }

    pub fn tenant_name(&self) -> &Str {
        &self.config.tenant_name
    }

    pub fn snapshot(&self) -> BudgetSnapshot {
        let max_credits = self.config.max_credits;
        let warn_at = self.config.warn_credits();
        self.state.read(|s| BudgetSnapshot {
            used_credits: s.used_credits,
            remaining_credits: max_credits.saturating_sub(s.used_credits),
            dispatched_jobs: s.dispatched_jobs,
            rejected_jobs: s.rejected_jobs,
            warning_active: s.used_credits >= warn_at,
        })
    }

    pub fn recent_audit(&self, limit: usize) -> Vec<AuditEntry> {
        self.state.read(|s| {
            let skip = s.audit_ring.len().saturating_sub(limit);
            s.audit_ring.iter().skip(skip).cloned().collect()
        })
    }

    pub fn reset_window(&self) -> u64 {
        self.state.with(|s| {
            let previous = s.used_credits;
            s.used_credits = 0;
            s.audit_ring.clear();
            previous
        })
    }

    pub fn can_afford(&self, cost: u64) -> bool {
        let max_credits = self.config.max_credits;
        self.state
            .read(|s| s.used_credits.saturating_add(cost) <= max_credits)
    }

    pub async fn submit_dispatch(&self, job: &DispatchJob) -> Result<u64, BudgetError> {
        job.validate()?;
        let max_credits = self.config.max_credits;
        let remaining = self.state.read(|s| max_credits.saturating_sub(s.used_credits));
        if remaining < job.credit_cost {
            self.state.with(|s| s.rejected_jobs += 1);
            return Err(BudgetError::InsufficientCredits {
                requested: job.credit_cost,
                remaining,
            });
        }

        enqueue_remote_job(job.job_id, &job.kind, job.payload_bytes)
            .await
            .map_err(BudgetError::DispatchFailed)?;

        let cap = self.config.max_audit_entries;
        let remaining_after = self.state.with(|s| {
            s.used_credits = s.used_credits.saturating_add(job.credit_cost);
            s.dispatched_jobs += 1;
            let rem = max_credits.saturating_sub(s.used_credits);
            s.record_audit(
                AuditEntry {
                    job_id: job.job_id,
                    cost: job.credit_cost,
                    remaining_after: rem,
                },
                cap,
            );
            rem
        });
        Ok(remaining_after)
    }
}

