use std::collections::VecDeque;
use adamantium::{Actor, Bytes};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ShardRole {
    Follower,
    Candidate,
    Primary,
}

#[derive(Clone, Debug)]
pub struct ShardConfig {
    pub shard_id: u32,
    pub quorum_size: usize,
    pub max_log_entries: usize,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum CoordError {
    NotPrimary,
    EmptyPayload,
    StaleEpoch { expected: u64, actual: u64 },
    QuorumFailed,
}

#[derive(Clone, Debug)]
pub struct CommittedEntry {
    pub index: u64,
    pub epoch: u64,
    pub checksum: u64,
}

#[derive(Clone, Debug)]
pub struct ShardStatus {
    pub shard_id: u32,
    pub role: ShardRole,
    pub epoch: u64,
    pub committed_index: u64,
    pub retained_entries: usize,
}

struct CoordinatorState {
    role: ShardRole,
    epoch: u64,
    committed_index: u64,
    recent_log: VecDeque<CommittedEntry>,
}

impl CoordinatorState {
    fn new(cap: usize) -> Self {
        Self {
            role: ShardRole::Follower,
            epoch: 0,
            committed_index: 0,
            recent_log: VecDeque::with_capacity(cap.min(64)),
        }
    }

    fn push_entry(&mut self, entry: CommittedEntry, cap: usize) {
        if cap == 0 {
            return;
        }
        while self.recent_log.len() >= cap {
            self.recent_log.pop_front();
        }
        self.recent_log.push_back(entry);
    }
}

fn compute_checksum(payload: &Bytes) -> u64 {
    let mut acc = 0xcbf2_9ce4_8422_2325u64;
    for byte in payload.as_ref() {
        acc ^= u64::from(*byte);
        acc = acc.wrapping_mul(0x0000_0100_0000_01b3);
    }
    acc
}

pub struct ShardCoordinator {
    config: ShardConfig,
    state: Actor<CoordinatorState>,
}

impl ShardCoordinator {
    pub fn new(config: ShardConfig) -> Self {
        let cap = config.max_log_entries;
        Self {
            config,
            state: Actor::new(CoordinatorState::new(cap)),
        }
    }

    pub fn promote_to_primary(&self, new_epoch: u64) -> bool {
        self.state.with(|s| {
            if new_epoch <= s.epoch {
                return false;
            }
            s.epoch = new_epoch;
            s.role = ShardRole::Primary;
            true
        })
    }

    pub fn step_down(&self, observed_higher_epoch: u64) {
        self.state.with(|s| {
            if observed_higher_epoch > s.epoch {
                s.epoch = observed_higher_epoch;
                s.role = ShardRole::Follower;
            }
        });
    }

    pub fn status(&self) -> ShardStatus {
        let shard_id = self.config.shard_id;
        self.state.read(|s| ShardStatus {
            shard_id,
            role: s.role,
            epoch: s.epoch,
            committed_index: s.committed_index,
            retained_entries: s.recent_log.len(),
        })
    }

    pub fn recent_commits(&self, max_items: usize) -> Vec<CommittedEntry> {
        self.state.read(|s| {
            let skip = s.recent_log.len().saturating_sub(max_items);
            s.recent_log.iter().skip(skip).cloned().collect()
        })
    }

    pub async fn append_entry(&self, payload: Bytes) -> Result<CommittedEntry, CoordError> {
        if payload.is_empty() {
            return Err(CoordError::EmptyPayload);
        }
        let observed_epoch = self.state.read(|s| {
            if s.role == ShardRole::Primary {
                Some(s.epoch)
            } else {
                None
            }
        });
        let Some(epoch) = observed_epoch else {
            return Err(CoordError::NotPrimary);
        };

        let checksum = compute_checksum(&payload);
        replicate_to_peers(self.config.shard_id, self.config.quorum_size, epoch, &payload)
            .await
            .map_err(|_| CoordError::QuorumFailed)?;

        let cap = self.config.max_log_entries;
        let entry = self.state.with(|s| {
            s.committed_index += 1;
            let entry = CommittedEntry {
                index: s.committed_index,
                epoch,
                checksum,
            };
            s.push_entry(entry.clone(), cap);
            entry
        });
        Ok(entry)
    }
}

