    pub max_entries: usize,
    pub region: Str,
}

#[derive(Clone, Debug)]
pub struct ProductRecord {
    pub sku: u64,
    pub title: Str,
    pub price_cents: u64,
    pub body: Bytes,
}

#[derive(Clone, Debug)]
pub struct CacheMetrics {
    pub hits: u64,
    pub misses: u64,
    pub evictions: u64,
    pub invalidations: u64,
    pub live_entries: usize,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum CatalogError {
    NotFound(u64),
    OriginUnavailable(Str),
}

struct CatalogState {
    generation: u64,
    entries: HashMap<u64, ProductRecord>,
    eviction_order: VecDeque<u64>,
    hits: u64,
    misses: u64,
    evictions: u64,
    invalidations: u64,
}

impl CatalogState {
    fn new(max_entries: usize) -> Self {
        Self {
            generation: 0,
            entries: HashMap::with_capacity(max_entries.min(256)),
            eviction_order: VecDeque::with_capacity(max_entries.min(256)),
            hits: 0,
            misses: 0,
            evictions: 0,
            invalidations: 0,
        }
    }

    fn insert_bounded(&mut self, record: ProductRecord, max_entries: usize) {
        if max_entries == 0 {
            return;
        }
        let sku = record.sku;
        let existed = self.entries.contains_key(&sku);
        if !existed {
            while self.entries.len() >= max_entries {
                let Some(oldest) = self.eviction_order.pop_front() else {
                    break;
                };
                if self.entries.remove(&oldest).is_some() {
                    self.evictions += 1;
                }
            }
            self.eviction_order.push_back(sku);
        }
        self.entries.insert(sku, record);
    }

    fn remove_key(&mut self, sku: u64) -> bool {
        if self.entries.remove(&sku).is_some() {
            self.eviction_order.retain(|&k| k != sku);
            true
        } else {
            false
        }
    }
}

pub struct CatalogCache {
    config: CatalogConfig,
    state: Actor<CatalogState>,
}

impl CatalogCache {
    pub fn new(config: CatalogConfig) -> Self {
        let cap = config.max_entries;
        Self {
            config,
            state: Actor::new(CatalogState::new(cap)),
        }
    }

    pub fn region(&self) -> &Str {
        &self.config.region
    }

    pub fn metrics(&self) -> CacheMetrics {
        self.state.read(|s| CacheMetrics {
            hits: s.hits,
            misses: s.misses,
            evictions: s.evictions,
            invalidations: s.invalidations,
            live_entries: s.entries.len(),
        })
    }

    pub fn update_product(&self, record: ProductRecord) {
        let cap = self.config.max_entries;
        self.state.with(|s| {
            s.generation += 1;
            s.insert_bounded(record, cap);
        });
    }

    pub fn invalidate(&self, sku: u64) -> bool {
        self.state.with(|s| {
            s.generation += 1;
            if s.remove_key(sku) {
                s.invalidations += 1;
                true
            } else {
                false
            }
        })
    }

    pub fn clear(&self) {
        self.state.with(|s| {
            s.generation += 1;
            s.entries.clear();
            s.eviction_order.clear();
        });
    }

    pub async fn get_or_fetch(&self, sku: u64) -> Result<ProductRecord, CatalogError> {
        let cached = self.state.with(|s| {
            if let Some(record) = s.entries.get(&sku).cloned() {
                s.hits += 1;
                Some(record)
            } else {
                s.misses += 1;
                None
            }
        });
        if let Some(record) = cached {
            return Ok(record);
        }

        let fetched = fetch_product_from_origin(&self.config.region, sku).await?;
        let cap = self.config.max_entries;
        self.state.with(|s| {
            s.generation += 1;
            s.insert_bounded(fetched.clone(), cap);
        });
        Ok(fetched)
    }
}

