            }
        })
    }

    pub fn clear(&self) {
        self.state.with(|s| {
            s.generation += 1;
            s.entries.clear();
            s.eviction_order.clear();
        });
    }

    pub async fn get_or_fetch(&self, sku: u64) -> Result<ProductRecord, CatalogError> {
        let (observed_gen, cached) = self.state.with(|s| {
            if let Some(record) = s.entries.get(&sku).cloned() {
                s.hits += 1;
                (s.generation, Some(record))
            } else {
                s.misses += 1;
                (s.generation, None)
            }
        });
        if let Some(record) = cached {
            return Ok(record);
        }

        let fetched = fetch_product_from_origin(&self.config.region, sku).await?;
        let cap = self.config.max_entries;
        let current = self.state.with(|s| {
            if s.generation == observed_gen {
                s.generation += 1;
                s.insert_bounded(fetched.clone(), cap);
                fetched
            } else if let Some(newer) = s.entries.get(&sku) {
                newer.clone()
            } else {
                fetched
            }
        });
        Ok(current)
    }
}

use std::collections::HashMap;
use adamantium::Actor;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum FlagKey {
    DarkMode,
    FastSearch,
    NewCheckout,
    SmartRetry,
    BatchExport,
    BetaDashboard,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct FlagRule {
    pub enabled: bool,
    pub rollout_pct: u8,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum FlagError {
    InvalidPercentage(u8),
    PolicyRejected,
}

#[derive(Clone)]
struct FlagTable {
    revision: u64,
    rules: HashMap<FlagKey, FlagRule>,
}

impl FlagTable {
    fn defaults() -> Self {
        let mut rules = HashMap::new();
        for key in [
            FlagKey::DarkMode,
            FlagKey::FastSearch,
            FlagKey::NewCheckout,
            FlagKey::SmartRetry,
            FlagKey::BatchExport,
            FlagKey::BetaDashboard,
        ] {
            rules.insert(
                key,
                FlagRule {
                    enabled: false,
                    rollout_pct: 0,
                },
            );
        }
        Self { revision: 1, rules }
    }
}

pub struct FeatureRegistry {
    table: Actor<FlagTable>,
}

impl FeatureRegistry {
    pub fn new() -> Self {
        Self {
            table: Actor::new(FlagTable::defaults()),
        }
    }

    pub fn revision(&self) -> u64 {
        self.table.read(|t| t.revision)
    }

    pub fn is_enabled(&self, key: FlagKey) -> bool {
        self.table
            .read(|t| t.rules.get(&key).map(|r| r.enabled).unwrap_or(false))
    }

    pub fn snapshot_rule(&self, key: FlagKey) -> Option<FlagRule> {
        self.table.read(|t| t.rules.get(&key).copied())
    }

    pub async fn patch_flag(&self, key: FlagKey, rule: FlagRule) -> Result<u64, FlagError> {
        if rule.rollout_pct > 100 {
            return Err(FlagError::InvalidPercentage(rule.rollout_pct));
        }

        let mut next = self.table.snapshot();
        next.rules.insert(key, rule);
        next.revision += 1;

        approve_flag_change(key, rule)
            .await
            .map_err(|_| FlagError::PolicyRejected)?;

        let rev = next.revision;
        self.table.with(|t| {
            *t = next;
        });
        Ok(rev)
    }
}

