use std::sync::atomic::{AtomicU64, Ordering};
use adamantium::{Bytes, Str};

#[derive(Clone, Debug)]
pub struct SegmentConfig {
    pub stream_name: Str,
    pub max_frame_bytes: usize,
    pub initial_offset: u64,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum SegmentError {
    EmptyFrame,
    FrameTooLarge { len: usize, max: usize },
    StorageFailed(Str),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct WriteReceipt {
    pub start_offset: u64,
    pub end_offset: u64,
}

impl WriteReceipt {
    pub fn written_bytes(self) -> u64 {
        self.end_offset.saturating_sub(self.start_offset)
    }
}

pub struct SegmentCheckpoint {
    config: SegmentConfig,
    cursor: AtomicU64,
}

impl SegmentCheckpoint {
    pub fn new(config: SegmentConfig) -> Self {
        let start = config.initial_offset;
        Self {
            config,
            cursor: AtomicU64::new(start),
        }
    }

    pub fn stream_name(&self) -> &Str {
        &self.config.stream_name
    }

    pub fn current_offset(&self) -> u64 {
        self.cursor.load(Ordering::Acquire)
    }

    pub fn validate_frame(&self, frame: &Bytes) -> Result<u64, SegmentError> {
        if frame.is_empty() {
            return Err(SegmentError::EmptyFrame);
        }
        if frame.len() > self.config.max_frame_bytes {
            return Err(SegmentError::FrameTooLarge {
                len: frame.len(),
                max: self.config.max_frame_bytes,
            });
        }
        Ok(frame.len() as u64)
    }

    pub async fn append_frame(&self, frame: Bytes) -> Result<WriteReceipt, SegmentError> {
        let len = self.validate_frame(&frame)?;
        let start = self.cursor.load(Ordering::Acquire);
        write_segment_chunk(&self.config.stream_name, start, &frame)
            .await
            .map_err(SegmentError::StorageFailed)?;
        let end = start + len;
        self.cursor.store(end, Ordering::Release);
        Ok(WriteReceipt {
            start_offset: start,
            end_offset: end,
        })
    }
}

