use std::collections::VecDeque;
use adamantium::{Actor, Bytes, Sender, Str};

#[derive(Clone, Debug)]
pub struct RelayConfig {
    pub topic: Str,
    pub max_queued: usize,
}

#[derive(Clone, Debug)]
pub struct Envelope {
    pub id: u64,
    pub topic: Str,
    pub payload: Bytes,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum RelayError {
    QueueFull { max_queued: usize },
    ChannelClosed,
}

#[derive(Clone, Copy, Debug)]
pub struct RelayStats {
    pub queued: usize,
    pub sent: u64,
    pub rejected: u64,
}

struct OutboxState {
    queue: VecDeque<Envelope>,
    sent: u64,
    rejected: u64,
}

pub struct OutboxRelay {
    config: RelayConfig,
    state: Actor<OutboxState>,
}

impl OutboxRelay {
    pub fn new(config: RelayConfig) -> Self {
        let cap = config.max_queued.min(256);
        Self {
            config,
            state: Actor::new(OutboxState {
                queue: VecDeque::with_capacity(cap),
                sent: 0,
                rejected: 0,
            }),
        }
    }

    pub fn stats(&self) -> RelayStats {
        self.state.read(|s| RelayStats {
            queued: s.queue.len(),
            sent: s.sent,
            rejected: s.rejected,
        })
    }

    pub fn enqueue(&self, id: u64, payload: Bytes) -> Result<(), RelayError> {
        let max_queued = self.config.max_queued;
        let topic = self.config.topic.clone();
        self.state.with(|s| {
            if s.queue.len() >= max_queued {
                s.rejected += 1;
                return Err(RelayError::QueueFull { max_queued });
            }
            s.queue.push_back(Envelope { id, topic, payload });
            Ok(())
        })
    }

    pub async fn flush_one(&self, tx: &Sender<Envelope>) -> Result<bool, RelayError> {
        let Some(front) = self.state.read(|s| s.queue.front().cloned()) else {
            return Ok(false);
        };
        tx.send(front).await.map_err(|_| RelayError::ChannelClosed)?;
        self.state.with(|s| {
            s.queue.pop_front();
            s.sent += 1;
        });
        Ok(true)
    }
}

use std::collections::VecDeque;
use adamantium::{AsyncActor, Bytes, Reply, Sender, Str, Tasks};

#[derive(Clone, Debug)]
pub struct RelayConfig {
    pub topic: Str,
    pub max_queued: usize,
}

#[derive(Clone, Debug)]
pub struct Envelope {
    pub id: u64,
    pub topic: Str,
    pub payload: Bytes,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum RelayError {
    QueueFull { max_queued: usize },
    ChannelClosed,
    ActorStopped,
}

#[derive(Clone, Copy, Debug)]
pub struct RelayStats {
    pub queued: usize,
    pub sent: u64,
    pub rejected: u64,
}

enum RelayCommand {
    Enqueue {
        id: u64,
        payload: Bytes,
        reply: Reply<Result<(), RelayError>>,
    },
    FlushOne {
        tx: Sender<Envelope>,
        reply: Reply<Result<bool, RelayError>>,
    },
    Stats {
        reply: Reply<RelayStats>,
    },
}

struct OutboxState {
    config: RelayConfig,
    queue: VecDeque<Envelope>,
    sent: u64,
    rejected: u64,
}

pub fn spawn_outbox_relay(
    tasks: &mut Tasks<RelayError>,
    config: RelayConfig,
) -> AsyncActor<RelayCommand> {
    let cap = config.max_queued.min(256);
    let initial = OutboxState {
        config,
        queue: VecDeque::with_capacity(cap),
        sent: 0,
        rejected: 0,
    };
    AsyncActor::new(tasks, initial, 64, |state, cmd| {
        Box::pin(async move {
            match cmd {
                RelayCommand::Enqueue { id, payload, reply } => {
                    let result = if state.queue.len() >= state.config.max_queued {
                        state.rejected += 1;
                        Err(RelayError::QueueFull {
                            max_queued: state.config.max_queued,
                        })
                    } else {
                        state.queue.push_back(Envelope {
                            id,
                            topic: state.config.topic.clone(),
                            payload,
                        });
                        Ok(())
                    };
                    let _ = reply.send(result);
                }
                RelayCommand::FlushOne { tx, reply } => {
                    let outcome = if let Some(front) = state.queue.front().cloned() {
                        match tx.send(front).await {
                            Ok(()) => {
                                state.queue.pop_front();
                                state.sent += 1;
                                Ok(true)
                            }
                            Err(_) => Err(RelayError::ChannelClosed),
                        }
                    } else {
                        Ok(false)
                    };
                    let _ = reply.send(outcome);
                }
                RelayCommand::Stats { reply } => {
                    let _ = reply.send(RelayStats {
                        queued: state.queue.len(),
                        sent: state.sent,
                        rejected: state.rejected,
                    });
                }
            }
            Ok(())
        })
    })
}

use std::collections::VecDeque;
use adamantium::{Actor, Str};

#[derive(Clone, Debug)]
pub struct AlertEvent {
    pub alert_id: u64,
    pub severity: u8,
    pub message: Str,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ForwardError {
    BacklogFull,
    DeliveryFailed(Str),
}

#[derive(Clone, Copy, Debug)]
pub struct ForwardStats {
    pub pending: usize,
    pub delivered: u64,
    pub dropped: u64,
}

struct AlertQueue {
    items: VecDeque<AlertEvent>,
    delivered: u64,
    dropped: u64,
}

pub struct AlertForwarder {
    max_pending: usize,
    queue: Actor<AlertQueue>,
}

impl AlertForwarder {
    pub fn new(max_pending: usize) -> Self {
        Self {
            max_pending,
            queue: Actor::new(AlertQueue {
                items: VecDeque::with_capacity(max_pending.min(128)),
                delivered: 0,
                dropped: 0,
            }),
        }
    }

    pub fn stats(&self) -> ForwardStats {
        self.queue.read(|q| ForwardStats {
            pending: q.items.len(),
            delivered: q.delivered,
            dropped: q.dropped,
        })
    }

    pub fn enqueue(&self, event: AlertEvent) -> Result<(), ForwardError> {
        let cap = self.max_pending;
        self.queue.with(|q| {
            if q.items.len() >= cap {
                q.dropped += 1;
                return Err(ForwardError::BacklogFull);
            }
            q.items.push_back(event);
            Ok(())
        })
    }

    pub async fn drain_next(&self) -> Result<bool, ForwardError> {
        let Some(event) = self.queue.read(|q| q.items.front().cloned()) else {
            return Ok(false);
        };
        deliver_alert(&event)
            .await
            .map_err(ForwardError::DeliveryFailed)?;
        self.queue.with(|q| {
            q.items.pop_front();
            q.delivered += 1;
        });
        Ok(true)
    }
}

use std::sync::{Arc, Mutex};
use adamantium::Str;

#[derive(Clone, Debug)]
pub struct BucketConfig {
    pub service_name: Str,
    pub capacity: u64,
    pub refill_step: u64,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum LimitError {
    Exhausted,
    UpstreamFailed(Str),
}

struct TokenBucket {
    available: u64,
    forwarded: u64,
}

pub struct RateLimiter {
    config: BucketConfig,
    bucket: Arc<Mutex<TokenBucket>>,
}

impl RateLimiter {
    pub fn new(config: BucketConfig) -> Self {
        let capacity = config.capacity;
        Self {
            config,
            bucket: Arc::new(Mutex::new(TokenBucket {
                available: capacity,
                forwarded: 0,
            })),
        }
    }

    pub fn refill(&self) {
        let mut guard = self.bucket.lock().unwrap();
        let next = guard.available.saturating_add(self.config.refill_step);
        guard.available = next.min(self.config.capacity);
    }

    pub fn available_tokens(&self) -> u64 {
        self.bucket.lock().unwrap().available
    }

    pub fn forwarded_count(&self) -> u64 {
        self.bucket.lock().unwrap().forwarded
    }

    pub async fn forward_weighted(&self, weight: u64, body: &[u8]) -> Result<(), LimitError> {
        let current = {
            let guard = self.bucket.lock().unwrap();
            guard.available
        };
        if current < weight {
            return Err(LimitError::Exhausted);
        }

        send_to_upstream(&self.config.service_name, body)
            .await
            .map_err(LimitError::UpstreamFailed)?;

        let mut guard = self.bucket.lock().unwrap();
        guard.available = current - weight;
        guard.forwarded += 1;
        Ok(())
    }
}

use std::sync::Arc;
use adamantium::{Bytes, Str};
use tokio::sync::Mutex;

#[derive(Clone, Debug)]
pub struct PublisherConfig {
    pub endpoint: Str,
    pub max_batch_bytes: usize,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum PublishError {
    EmptyPayload,
    TooLarge { len: usize, max: usize },
    Transport(Str),
}

struct PublisherState {
    next_sequence: u64,
    published_bytes: u64,
}

pub struct SerialPublisher {
    config: PublisherConfig,
    state: Arc<Mutex<PublisherState>>,
}

impl SerialPublisher {
    pub fn new(config: PublisherConfig) -> Self {
        Self {
            config,
            state: Arc::new(Mutex::new(PublisherState {
                next_sequence: 1,
                published_bytes: 0,
            })),
        }
    }

    pub fn endpoint(&self) -> &Str {
        &self.config.endpoint
    }

    pub fn validate(&self, payload: &Bytes) -> Result<(), PublishError> {
        if payload.is_empty() {
            return Err(PublishError::EmptyPayload);
        }
        if payload.len() > self.config.max_batch_bytes {
            return Err(PublishError::TooLarge {
                len: payload.len(),
                max: self.config.max_batch_bytes,
            });
        }
        Ok(())
    }

    pub async fn publish_next(&self, payload: Bytes) -> Result<u64, PublishError> {
        self.validate(&payload)?;
        let mut guard = self.state.lock().await;
        let seq = guard.next_sequence;
        send_ordered_frame(&self.config.endpoint, seq, &payload)
            .await
            .map_err(PublishError::Transport)?;
        guard.next_sequence = seq + 1;
        guard.published_bytes += payload.len() as u64;
        Ok(seq)
    }
}

use crate::external_ledger::{AccountSnapshot, LedgerError, SettlementLedger};
use adamantium::Str;

#[derive(Clone, Debug)]
pub struct SettlementConfig {
    pub currency: Str,
    pub max_single_payout: u64,
}

#[derive(Clone, Debug)]
pub struct PayoutRequest {
    pub account_id: u64,
    pub amount: u64,
    pub reference: Str,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum PayoutError {
    ZeroAmount,
    ExceedsLimit { amount: u64, max: u64 },
    InsufficientFunds,
    Ledger(LedgerError),
    GatewayFailed(Str),
}

#[derive(Clone, Debug)]
pub struct PayoutReceipt {
    pub account_id: u64,
    pub settled_amount: u64,
    pub new_balance: u64,
}

pub struct PayoutCoordinator<'a> {
    config: SettlementConfig,
    ledger: &'a SettlementLedger,
}

impl<'a> PayoutCoordinator<'a> {
    pub fn new(config: SettlementConfig, ledger: &'a SettlementLedger) -> Self {
        Self { config, ledger }
    }

    pub fn validate(&self, req: &PayoutRequest) -> Result<(), PayoutError> {
        if req.amount == 0 {
            return Err(PayoutError::ZeroAmount);
        }
        if req.amount > self.config.max_single_payout {
            return Err(PayoutError::ExceedsLimit {
                amount: req.amount,
                max: self.config.max_single_payout,
            });
        }
        Ok(())
    }

    pub async fn settle(&self, req: &PayoutRequest) -> Result<PayoutReceipt, PayoutError> {
        self.validate(req)?;
        let snapshot: AccountSnapshot = self
            .ledger
            .fetch_account(req.account_id)
            .map_err(PayoutError::Ledger)?;
        if snapshot.available_balance() < req.amount {
            return Err(PayoutError::InsufficientFunds);
        }

        execute_bank_wire(&self.config.currency, req.account_id, req.amount, &req.reference)
            .await
            .map_err(PayoutError::GatewayFailed)?;

        let new_balance = self
            .ledger
            .commit_debit(&snapshot, req.amount)
            .map_err(PayoutError::Ledger)?;
        Ok(PayoutReceipt {
            account_id: req.account_id,
            settled_amount: req.amount,
            new_balance,
        })
    }
}

