    state: Actor<DnsCacheState>,
}

impl DnsResolverCache {
    pub fn new(config: DnsCacheConfig) -> Self {
        Self {
            config,
            state: Actor::new(DnsCacheState::new()),
        }
    }

    pub fn region(&self) -> &Str {
        &self.config.region
    }

    pub fn stats(&self) -> DnsStats {
        self.state.read(|s| DnsStats {
            entries: s.records.len(),
            hits: s.hits,
            misses: s.misses,
            stale_hits: s.stale_hits,
        })
    }

    pub fn lookup(&self, host: &str, now_secs: u64) -> Option<IpAddr> {
        self.state.with(|s| {
            let Some(record) = s.records.get(host) else {
                s.misses += 1;
                return None;
            };
            if record.is_fresh(now_secs) {
                s.hits += 1;
                Some(record.address)
            } else {
                s.stale_hits += 1;
                None
            }
        })
    }

    pub fn put_record(
        &self,
        host: Str,
        address: IpAddr,
        now_secs: u64,
        ttl_secs: u64,
    ) -> Result<DnsRecord, DnsCacheError> {
        if host.is_empty() {
            return Err(DnsCacheError::EmptyHost);
        }
        let clamped_ttl = self.config.clamp_ttl(ttl_secs);
        let record = DnsRecord {
            host: host.clone(),
            address,
            expires_at_secs: now_secs.saturating_add(clamped_ttl),
        };
        self.state.with(|s| {
            s.records.insert(host, record.clone());
        });
        Ok(record)
    }

    pub fn hosts_for_ip(&self, target: IpAddr, now_secs: u64) -> Vec<Str> {
        self.state.read(|s| {
            s.records
                .values()
                .filter(|r| r.address == target && r.is_fresh(now_secs))
                .map(|r| r.host.clone())
                .collect()
        })
    }

    pub fn fresh_count(&self, now_secs: u64) -> usize {
        self.state
            .read(|s| s.records.values().filter(|r| r.is_fresh(now_secs)).count())
    }
}

use std::collections::{HashMap, VecDeque};
use std::net::IpAddr;
use adamantium::{Actor, Str};

#[derive(Clone, Debug)]
pub struct DnsCacheConfig {
    pub default_ttl_secs: u64,
    pub max_ttl_secs: u64,
    pub max_entries: usize,
    pub region: Str,
}

impl DnsCacheConfig {
    pub fn clamp_ttl(&self, requested: u64) -> u64 {
        if requested == 0 {
            self.default_ttl_secs
        } else {
            requested.min(self.max_ttl_secs)
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DnsRecord {
    pub host: Str,
    pub address: IpAddr,
    pub expires_at_secs: u64,
}

impl DnsRecord {
    pub fn is_fresh(&self, now_secs: u64) -> bool {
        self.expires_at_secs > now_secs
    }
}

#[derive(Clone, Copy, Debug)]
pub struct DnsStats {
    pub entries: usize,
    pub hits: u64,
    pub misses: u64,
    pub stale_hits: u64,
    pub evictions: u64,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum DnsCacheError {
    EmptyHost,
}

struct DnsCacheState {
    records: HashMap<Str, DnsRecord>,
    order: VecDeque<Str>,
    hits: u64,
    misses: u64,
    stale_hits: u64,
    evictions: u64,
}

impl DnsCacheState {
    fn new(cap: usize) -> Self {
        Self {
            records: HashMap::with_capacity(cap.min(256)),
            order: VecDeque::with_capacity(cap.min(256)),
            hits: 0,
            misses: 0,
            stale_hits: 0,
            evictions: 0,
        }
    }

    fn evict_expired(&mut self, now_secs: u64) {
        self.records.retain(|_, rec| rec.is_fresh(now_secs));
        self.order.retain(|host| self.records.contains_key(host));
    }

    fn insert_capped(&mut self, host: Str, record: DnsRecord, cap: usize) {
        if cap == 0 {
            return;
        }
        if !self.records.contains_key(&host) {
            while self.records.len() >= cap {
                let Some(oldest) = self.order.pop_front() else {
                    break;
                };
                if self.records.remove(&oldest).is_some() {
                    self.evictions += 1;
                }
            }
            self.order.push_back(host.clone());
        }
        self.records.insert(host, record);
    }
}

pub struct DnsResolverCache {
    config: DnsCacheConfig,
    state: Actor<DnsCacheState>,
}

impl DnsResolverCache {
    pub fn new(config: DnsCacheConfig) -> Self {
        let cap = config.max_entries;
        Self {
            config,
            state: Actor::new(DnsCacheState::new(cap)),
        }
    }

    pub fn region(&self) -> &Str {
        &self.config.region
    }

    pub fn stats(&self) -> DnsStats {
        self.state.read(|s| DnsStats {
            entries: s.records.len(),
            hits: s.hits,
            misses: s.misses,
            stale_hits: s.stale_hits,
            evictions: s.evictions,
        })
    }

    pub fn lookup(&self, host: &str, now_secs: u64) -> Option<IpAddr> {
        self.state.with(|s| {
            let Some(record) = s.records.get(host) else {
                s.misses += 1;
                return None;
            };
            if record.is_fresh(now_secs) {
                s.hits += 1;
                Some(record.address)
            } else {
                s.stale_hits += 1;
                s.records.remove(host);
                s.order.retain(|k| k.as_str() != host);
                None
            }
        })
    }

    pub fn put_record(
        &self,
        host: Str,
        address: IpAddr,
        now_secs: u64,
        ttl_secs: u64,
    ) -> Result<DnsRecord, DnsCacheError> {
        if host.is_empty() {
            return Err(DnsCacheError::EmptyHost);
        }
        let clamped_ttl = self.config.clamp_ttl(ttl_secs);
        let cap = self.config.max_entries;
        let record = DnsRecord {
            host: host.clone(),
            address,
            expires_at_secs: now_secs.saturating_add(clamped_ttl),
        };
        self.state.with(|s| {
            if s.records.len() >= cap {
                s.evict_expired(now_secs);
            }
            s.insert_capped(host, record.clone(), cap);
        });
        Ok(record)
    }

    pub fn prune_expired(&self, now_secs: u64) -> usize {
        self.state.with(|s| {
            let before = s.records.len();
            s.evict_expired(now_secs);
            before.saturating_sub(s.records.len())
        })
    }
}

use std::collections::HashMap;
use adamantium::{Actor, Str};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct LockOwner {
    pub worker_id: u32,
    pub acquired_at_ms: u64,
    pub reason: Str,
}

#[derive(Clone, Debug)]
pub struct LockEvent {
    pub resource_id: u64,
    pub worker_id: u32,
    pub timestamp_ms: u64,
    pub acquired: bool,
}

#[derive(Clone, Copy, Debug)]
pub struct LockStats {
    pub active_locks: usize,
    pub total_acquires: u64,
    pub total_releases: u64,
    pub contentions: u64,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum LockError {
    AlreadyHeld { resource_id: u64, holder: u32 },
    NotHeldByCaller { resource_id: u64 },
}

struct LockTableState {
    owners: HashMap<u64, LockOwner>,
    event_log: Vec<LockEvent>,
    total_acquires: u64,
    total_releases: u64,
    contentions: u64,
}

impl LockTableState {
    fn new() -> Self {
        Self {
            owners: HashMap::new(),
            event_log: Vec::new(),
            total_acquires: 0,
            total_releases: 0,
            contentions: 0,
        }
    }
}

pub struct AdvisoryLockTable {
    namespace: Str,
    state: Actor<LockTableState>,
}

impl AdvisoryLockTable {
    pub fn new(namespace: Str) -> Self {
        Self {
            namespace,
            state: Actor::new(LockTableState::new()),
        }
    }

    pub fn namespace(&self) -> &Str {
        &self.namespace
    }

    pub fn stats(&self) -> LockStats {
        self.state.read(|s| LockStats {
            active_locks: s.owners.len(),
            total_acquires: s.total_acquires,
            total_releases: s.total_releases,
            contentions: s.contentions,
        })
    }

    pub fn holder_of(&self, resource_id: u64) -> Option<u32> {
        self.state
            .read(|s| s.owners.get(&resource_id).map(|o| o.worker_id))
    }

    pub fn try_acquire(
        &self,
        resource_id: u64,
        worker_id: u32,
        now_ms: u64,
        reason: Str,
    ) -> Result<(), LockError> {
        self.state.with(|s| {
            if let Some(existing) = s.owners.get(&resource_id) {
                if existing.worker_id != worker_id {
                    s.contentions += 1;
                    return Err(LockError::AlreadyHeld {
                        resource_id,
                        holder: existing.worker_id,
                    });
                }
                return Ok(());
            }
            s.owners.insert(
                resource_id,
                LockOwner {
                    worker_id,
                    acquired_at_ms: now_ms,
                    reason,
                },
            );
            s.total_acquires += 1;
            s.event_log.push(LockEvent {
                resource_id,
                worker_id,
                timestamp_ms: now_ms,
                acquired: true,
            });
            Ok(())
        })
    }

    pub fn release(&self, resource_id: u64, worker_id: u32, now_ms: u64) -> Result<(), LockError> {
        self.state.with(|s| {
            let owned = s
                .owners
                .get(&resource_id)
                .is_some_and(|owner| owner.worker_id == worker_id);
            if !owned {
                return Err(LockError::NotHeldByCaller { resource_id });
            }
            s.owners.remove(&resource_id);
            s.total_releases += 1;
            s.event_log.push(LockEvent {
                resource_id,
                worker_id,
                timestamp_ms: now_ms,
                acquired: false,
            });
            Ok(())
        })
    }

    pub fn release_all_for_worker(&self, worker_id: u32) -> usize {
        self.state.with(|s| {
            let before = s.owners.len();
            s.owners.retain(|_, owner| owner.worker_id != worker_id);
            let removed = before.saturating_sub(s.owners.len());
            s.total_releases += removed as u64;
            removed
        })
    }

    pub fn recent_events(&self, limit: usize) -> Vec<LockEvent> {
        self.state.read(|s| {
            let start = s.event_log.len().saturating_sub(limit);
            s.event_log[start..].to_vec()
        })
    }
}

