    event_ring: VecDeque<LockEvent>,
    total_acquires: u64,
    total_releases: u64,
    contentions: u64,
}

impl LockTableState {
    fn new(max_events: usize) -> Self {
        Self {
            owners: HashMap::new(),
            event_ring: VecDeque::with_capacity(max_events.min(128)),
            total_acquires: 0,
            total_releases: 0,
            contentions: 0,
        }
    }

    fn push_event(&mut self, event: LockEvent, cap: usize) {
        if cap == 0 {
            return;
        }
        while self.event_ring.len() >= cap {
            self.event_ring.pop_front();
        }
        self.event_ring.push_back(event);
    }
}

