    completed_responses: u64,
    unknown_responses: u64,
}

impl MultiplexerState {
    fn new() -> Self {
        Self {
            next_id: 1,
            pending: HashMap::new(),
            sent_requests: 0,
            completed_responses: 0,
            unknown_responses: 0,
        }
    }
}

pub struct MultiplexedClient {
    config: RpcClientConfig,
    state: Actor<MultiplexerState>,
}

impl MultiplexedClient {
    pub fn new(config: RpcClientConfig) -> Self {
        Self {
            config,
            state: Actor::new(MultiplexerState::new()),
        }
    }

    pub fn service_name(&self) -> &Str {
        &self.config.service_name
    }

    pub fn stats(&self) -> RpcStats {
        self.state.read(|s| RpcStats {
            in_flight: s.pending.len(),
            sent_requests: s.sent_requests,
            completed_responses: s.completed_responses,
            unknown_responses: s.unknown_responses,
        })
    }

    pub fn validate_payload(&self, body: &Bytes) -> Result<(), RpcError> {
        if body.len() > self.config.max_payload_bytes {
            return Err(RpcError::PayloadTooLarge {
                len: body.len(),
                max: self.config.max_payload_bytes,
            });
        }
        Ok(())
    }

    pub fn register_request(
        &self,
        method: Str,
        body: &Bytes,
    ) -> Result<(u64, ReplyReceiver<Bytes>), RpcError> {
        self.validate_payload(body)?;
        self.state.with(|s| {
            let req_id = s.next_id;
            s.next_id += 1;
            let (reply, rx) = Reply::pair();
            if s.pending.contains_key(&req_id) {
                return Err(RpcError::DuplicateRequestId(req_id));
            }
            s.pending.insert(req_id, PendingEntry { method, reply });
            s.sent_requests += 1;
            Ok((req_id, rx))
        })
    }

    pub async fn call(&self, method: Str, body: Bytes) -> Result<Bytes, RpcError> {
        let (req_id, rx) = self.register_request(method, &body)?;
        write_wire_frame(&self.config.service_name, req_id, &body)
            .await
            .map_err(|_| RpcError::TransportClosed)?;
        rx.receive().await.ok_or(RpcError::PeerDisconnected)
    }

    pub fn on_response_frame(&self, req_id: u64, payload: Bytes) -> bool {
        let entry = self.state.with(|s| match s.pending.remove(&req_id) {
            Some(entry) => {
                s.completed_responses += 1;
                Some(entry)
            }
            None => {
                s.unknown_responses += 1;
                None
            }
        });
        if let Some(entry) = entry {
            let _ = entry.method;
            let _ = entry.reply.send(payload);
            true
        } else {
            false
        }
    }
}

use std::collections::HashMap;
use adamantium::{Actor, Bytes, Reply, Str};

#[derive(Clone, Debug)]
pub struct RpcClientConfig {
    pub service_name: Str,
    pub max_payload_bytes: usize,
    pub max_in_flight: usize,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum RpcError {
    PayloadTooLarge { len: usize, max: usize },
    TooManyInFlight { limit: usize },
    TransportClosed,
    PeerDisconnected,
}

#[derive(Clone, Copy, Debug)]
pub struct RpcStats {
    pub in_flight: usize,
    pub sent_requests: u64,
    pub completed_responses: u64,
    pub unknown_responses: u64,
    pub cancelled_requests: u64,
}

struct PendingEntry {
    method: Str,
    reply: Reply<Bytes>,
}

struct MultiplexerState {
    next_id: u64,
    pending: HashMap<u64, PendingEntry>,
    sent_requests: u64,
    completed_responses: u64,
    unknown_responses: u64,
    cancelled_requests: u64,
}

impl MultiplexerState {
    fn new(cap: usize) -> Self {
        Self {
            next_id: 1,
            pending: HashMap::with_capacity(cap.min(256)),
            sent_requests: 0,
            completed_responses: 0,
            unknown_responses: 0,
            cancelled_requests: 0,
        }
    }
}

struct InFlightGuard {
    state: Actor<MultiplexerState>,
    req_id: u64,
}

impl Drop for InFlightGuard {
    fn drop(&mut self) {
        self.state.with(|s| {
            if s.pending.remove(&self.req_id).is_some() {
                s.cancelled_requests += 1;
            }
        });
    }
}

pub struct MultiplexedClient {
    config: RpcClientConfig,
    state: Actor<MultiplexerState>,
}

impl MultiplexedClient {
    pub fn new(config: RpcClientConfig) -> Self {
        let cap = config.max_in_flight;
        Self {
            config,
            state: Actor::new(MultiplexerState::new(cap)),
        }
    }

    pub fn service_name(&self) -> &Str {
        &self.config.service_name
    }

    pub fn stats(&self) -> RpcStats {
        self.state.read(|s| RpcStats {
            in_flight: s.pending.len(),
            sent_requests: s.sent_requests,
            completed_responses: s.completed_responses,
            unknown_responses: s.unknown_responses,
            cancelled_requests: s.cancelled_requests,
        })
    }

    pub fn validate_payload(&self, body: &Bytes) -> Result<(), RpcError> {
        if body.len() > self.config.max_payload_bytes {
            return Err(RpcError::PayloadTooLarge {
                len: body.len(),
                max: self.config.max_payload_bytes,
            });
        }
        Ok(())
    }

    pub async fn call(&self, method: Str, body: Bytes) -> Result<Bytes, RpcError> {
        self.validate_payload(&body)?;
        let max_in_flight = self.config.max_in_flight;
        let (req_id, rx) = self.state.with(|s| {
            if s.pending.len() >= max_in_flight {
                return Err(RpcError::TooManyInFlight {
                    limit: max_in_flight,
                });
            }
            let req_id = s.next_id;
            s.next_id += 1;
            let (reply, rx) = Reply::pair();
            s.pending.insert(req_id, PendingEntry { method, reply });
            s.sent_requests += 1;
            Ok((req_id, rx))
        })?;
        let _guard = InFlightGuard {
            state: self.state.clone(),
            req_id,
        };

        write_wire_frame(&self.config.service_name, req_id, &body)
            .await
            .map_err(|_| RpcError::TransportClosed)?;
        rx.receive().await.ok_or(RpcError::PeerDisconnected)
    }

    pub fn on_response_frame(&self, req_id: u64, payload: Bytes) -> bool {
        let entry = self.state.with(|s| match s.pending.remove(&req_id) {
            Some(entry) => {
                s.completed_responses += 1;
                Some(entry)
            }
            None => {
                s.unknown_responses += 1;
                None
            }
        });
        if let Some(entry) = entry {
            let _ = entry.method;
            let _ = entry.reply.send(payload);
            true
        } else {
            false
        }
    }
}

