#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DeliveryOutcome {
    Accepted,
    TimedOut,
    HttpError(u16),
}

#[derive(Clone, Debug)]
pub struct DeliveryRecord {
    pub webhook_id: u64,
    pub target_host: Str,
    pub latency_ms: u32,
    pub outcome: DeliveryOutcome,
}

#[derive(Clone, Copy, Debug)]
pub struct TrackerSummary {
    pub recorded: usize,
    pub accepted: u64,
    pub failed: u64,
}

struct TrackerState {
    history: VecDeque<DeliveryRecord>,
    accepted: u64,
    failed: u64,
}

pub struct WebhookTracker {
    service: Str,
    state: Actor<TrackerState>,
}

impl WebhookTracker {
    pub fn new(service: Str) -> Self {
        Self {
            service,
            state: Actor::new(TrackerState {
                history: VecDeque::new(),
                accepted: 0,
                failed: 0,
            }),
        }
    }

    pub fn service(&self) -> &Str {
        &self.service
    }

    pub fn summary(&self) -> TrackerSummary {
        self.state.read(|s| TrackerSummary {
            recorded: s.history.len(),
            accepted: s.accepted,
            failed: s.failed,
        })
    }

    pub fn record(&self, entry: DeliveryRecord) {
        self.state.with(|s| {
            match entry.outcome {
                DeliveryOutcome::Accepted => s.accepted += 1,
                DeliveryOutcome::TimedOut | DeliveryOutcome::HttpError(_) => s.failed += 1,
            }
            s.history.push_back(entry);
        });
    }

    pub fn recent(&self, count: usize) -> Vec<DeliveryRecord> {
        self.state.read(|s| {
            let skip = s.history.len().saturating_sub(count);
            s.history.iter().skip(skip).cloned().collect()
        })
    }

    pub fn average_latency_ms(&self) -> Option<u32> {
        self.state.read(|s| {
            if s.history.is_empty() {
                return None;
            }
            let total: u64 = s.history.iter().map(|r| u64::from(r.latency_ms)).sum();
            Some((total / s.history.len() as u64) as u32)
        })
    }
}

