#[derive(Clone, Debug)]
pub struct IngestConfig {
    pub pipeline_name: Str,
    pub max_event_bytes: usize,
}

#[derive(Clone, Debug)]
pub struct IngestEvent {
    pub sequence: u64,
    pub tenant: Str,
    pub payload: Bytes,
}

#[derive(Clone, Copy, Debug, Default)]
pub struct IngestSummary {
    pub accepted: u64,
    pub oversized: u64,
    pub bytes_processed: u64,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum IngestError {
    SinkUnavailable(Str),
}

fn should_accept(config: &IngestConfig, event: &IngestEvent) -> bool {
    !event.payload.is_empty() && event.payload.len() <= config.max_event_bytes
}

pub async fn run_ingest_worker(
    config: IngestConfig,
    cancel: Cancellation,
    rx: Receiver<IngestEvent>,
) -> Result<IngestSummary, IngestError> {
    let mut summary = IngestSummary::default();
    let _ = Tasks::run_until(cancel, None, async |_tasks| {
        let mut archived_events: Vec<IngestEvent> = Vec::new();
        while let Some(event) = rx.receive().await {
            if !should_accept(&config, &event) {
                summary.oversized += 1;
                continue;
            }
            summary.accepted += 1;
            summary.bytes_processed += event.payload.len() as u64;
            forward_event(&config.pipeline_name, &event)
                .await
                .map_err(IngestError::SinkUnavailable)?;
            archived_events.push(event);
        }
        let _ = archived_events.len();
        Ok::<(), IngestError>(())
    })
    .await;
    Ok(summary)
}

use adamantium::{Bytes, Cancellation, Receiver, Str, Tasks};

const MAX_BATCH_EVENTS: usize = 64;

#[derive(Clone, Debug)]
pub struct IngestConfig {
    pub pipeline_name: Str,
    pub max_event_bytes: usize,
}

#[derive(Clone, Debug)]
pub struct IngestEvent {
    pub sequence: u64,
    pub tenant: Str,
    pub payload: Bytes,
}

#[derive(Clone, Copy, Debug, Default)]
pub struct IngestSummary {
    pub accepted: u64,
    pub oversized: u64,
    pub flushes: u64,
    pub bytes_processed: u64,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum IngestError {
    SinkUnavailable(Str),
}

fn should_accept(config: &IngestConfig, event: &IngestEvent) -> bool {
    !event.payload.is_empty() && event.payload.len() <= config.max_event_bytes
}

pub async fn run_ingest_worker(
    config: IngestConfig,
    cancel: Cancellation,
    rx: Receiver<IngestEvent>,
) -> Result<IngestSummary, IngestError> {
    let mut summary = IngestSummary::default();
    let _ = Tasks::run_until(cancel, None, async |_tasks| {
        let mut batch: Vec<IngestEvent> = Vec::with_capacity(MAX_BATCH_EVENTS);
        while let Some(event) = rx.receive().await {
            if !should_accept(&config, &event) {
                summary.oversized += 1;
                continue;
            }
            summary.accepted += 1;
            summary.bytes_processed += event.payload.len() as u64;
            batch.push(event);
            if batch.len() >= MAX_BATCH_EVENTS {
                flush_batch(&config.pipeline_name, &batch)
                    .await
                    .map_err(IngestError::SinkUnavailable)?;
                batch.clear();
                summary.flushes += 1;
            }
        }
        if !batch.is_empty() {
            flush_batch(&config.pipeline_name, &batch)
                .await
                .map_err(IngestError::SinkUnavailable)?;
            batch.clear();
            summary.flushes += 1;
        }
        Ok::<(), IngestError>(())
    })
    .await;
    Ok(summary)
}

use std::collections::HashMap;
use std::net::SocketAddr;
