#[derive(Clone, Copy, Debug, Default)]
pub struct PeerCounters {
    pub packets: u64,
    pub bytes: u64,
    pub last_seen_secs: u64,
}

#[derive(Clone, Debug)]
pub struct PeerSummary {
    pub addr: SocketAddr,
    pub packets: u64,
    pub bytes: u64,
}

pub struct PeerDirectory {
    cluster_name: Str,
    peers: Arc<Mutex<HashMap<SocketAddr, PeerCounters>>>,
}

impl PeerDirectory {
    pub fn new(cluster_name: Str) -> Self {
        Self {
            cluster_name,
            peers: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    pub fn cluster_name(&self) -> &Str {
        &self.cluster_name
    }

    pub fn record_packet(&self, addr: SocketAddr, bytes: u64, now_secs: u64) {
        let mut table = self.peers.lock().unwrap();
        let entry = table.entry(addr).or_default();
        entry.packets += 1;
        entry.bytes = entry.bytes.saturating_add(bytes);
        entry.last_seen_secs = now_secs;
    }

    pub fn known_peer_count(&self) -> usize {
        self.peers.lock().unwrap().len()
    }

    pub fn top_talkers(&self, min_packets: u64) -> Vec<PeerSummary> {
        let table = self.peers.lock().unwrap();
        table
            .iter()
            .filter(|(_, c)| c.packets >= min_packets)
            .map(|(&addr, c)| PeerSummary {
                addr,
                packets: c.packets,
                bytes: c.bytes,
            })
            .collect()
    }
}

use std::collections::VecDeque;
use std::sync::{Arc, Mutex};
use adamantium::Str;
use tokio::sync::broadcast;

const MAX_SAMPLES: usize = 512;
const BROADCAST_CAPACITY: usize = 128;

#[derive(Clone, Copy, Debug)]
pub struct MetricSample {
    pub timestamp_ms: u64,
    pub cpu_permille: u16,
    pub mem_mib: u32,
}

#[derive(Clone, Copy, Debug)]
pub struct RingSummary {
    pub count: usize,
    pub peak_cpu_permille: u16,
    pub peak_mem_mib: u32,
}

pub struct TelemetryRing {
    node_name: Str,
    samples: Arc<Mutex<VecDeque<MetricSample>>>,
    events: broadcast::Sender<MetricSample>,
}

impl TelemetryRing {
    pub fn new(node_name: Str) -> Self {
        let (events, _) = broadcast::channel(BROADCAST_CAPACITY);
        Self {
            node_name,
            samples: Arc::new(Mutex::new(VecDeque::with_capacity(MAX_SAMPLES))),
            events,
        }
    }

    pub fn node_name(&self) -> &Str {
        &self.node_name
    }

    pub fn subscribe(&self) -> broadcast::Receiver<MetricSample> {
        self.events.subscribe()
    }

    pub fn record(&self, sample: MetricSample) {
        {
            let mut ring = self.samples.lock().unwrap();
            while ring.len() >= MAX_SAMPLES {
                ring.pop_front();
            }
            ring.push_back(sample);
        }
        let _ = self.events.send(sample);
    }

    pub fn summary(&self) -> RingSummary {
        let ring = self.samples.lock().unwrap();
        let mut peak_cpu = 0u16;
        let mut peak_mem = 0u32;
        for sample in ring.iter() {
            peak_cpu = peak_cpu.max(sample.cpu_permille);
            peak_mem = peak_mem.max(sample.mem_mib);
        }
        RingSummary {
            count: ring.len(),
            peak_cpu_permille: peak_cpu,
            peak_mem_mib: peak_mem,
        }
    }
}

