    pub now_secs: u64,
}

pub struct IngressGuard {
    config: GuardConfig,
    store: BucketStore,
}

impl IngressGuard {
    pub fn new(config: GuardConfig, store: BucketStore) -> Self {
        Self { config, store }
    }

    pub fn service(&self) -> &Str {
        &self.config.service
    }

    pub fn burst_limit(&self) -> u32 {
        self.config.burst_limit
    }

    pub fn check_request(&self, hit: &ClientHit) -> CheckOutcome {
        let weight = hit.weight.max(1);
        match self.store.record_hit(
            hit.ip,
            weight,
            hit.now_secs,
            self.config.burst_limit,
            self.config.window_secs,
        ) {
            RateDecision::Allow(remaining) => CheckOutcome::Allowed { remaining },
            RateDecision::Deny => CheckOutcome::Throttled,
        }
    }

    pub fn is_known_client(&self, ip: IpAddr) -> bool {
        self.store.contains(ip)
    }
}

use std::collections::{HashMap, VecDeque};
use adamantium::{Actor, Bytes, Str};

#[derive(Clone, Debug)]
pub struct AssetCacheConfig {
    pub bucket_name: Str,
    pub max_assets: usize,
    pub max_blob_bytes: usize,
}

#[derive(Clone, Debug)]
pub struct AssetBlob {
    pub key: Str,
    pub content_type: Str,
    pub data: Bytes,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum AssetError {
    EmptyKey,
    BlobTooLarge { len: usize, max: usize },
}

#[derive(Clone, Copy, Debug)]
pub struct AssetCacheStats {
    pub entry_count: usize,
    pub queue_len: usize,
}

pub struct AssetCache {
    config: AssetCacheConfig,
    entries: Actor<HashMap<Str, AssetBlob>>,
    eviction_order: Actor<VecDeque<Str>>,
}

impl AssetCache {
    pub fn new(config: AssetCacheConfig) -> Self {
        let cap = config.max_assets.min(256);
        Self {
            config,
            entries: Actor::new(HashMap::with_capacity(cap)),
            eviction_order: Actor::new(VecDeque::with_capacity(cap)),
        }
    }

    pub fn bucket_name(&self) -> &Str {
        &self.config.bucket_name
    }

    pub fn validate(&self, blob: &AssetBlob) -> Result<(), AssetError> {
        if blob.key.is_empty() {
            return Err(AssetError::EmptyKey);
        }
        if blob.data.len() > self.config.max_blob_bytes {
            return Err(AssetError::BlobTooLarge {
                len: blob.data.len(),
                max: self.config.max_blob_bytes,
            });
        }
        Ok(())
    }

    pub fn stats(&self) -> AssetCacheStats {
        let entry_count = self.entries.read(HashMap::len);
        let queue_len = self.eviction_order.read(VecDeque::len);
        AssetCacheStats {
            entry_count,
            queue_len,
        }
    }

    pub fn get(&self, key: &str) -> Option<AssetBlob> {
        self.entries.read(|map| map.get(key).cloned())
    }

    pub fn put(&self, blob: AssetBlob) -> Result<(), AssetError> {
        self.validate(&blob)?;
        if self.config.max_assets == 0 {
            return Ok(());
        }
        let key = blob.key.clone();
        let evicted = self.eviction_order.with(|order| {
            if !order.iter().any(|existing| existing == &key) {
                order.push_back(key.clone());
            }
            if order.len() > self.config.max_assets {
                order.pop_front()
            } else {
                None
            }
        });
        self.entries.with(|map| {
            if let Some(old_key) = evicted {
                map.remove(&old_key);
            }
            map.insert(key, blob);
        });
        Ok(())
    }

    pub fn remove(&self, key: &str) -> bool {
        self.eviction_order.with(|order| {
            order.retain(|existing| existing.as_str() != key);
        });
        self.entries.with(|map| map.remove(key).is_some())
    }

    pub fn clear(&self) {
        self.eviction_order.with(VecDeque::clear);
        self.entries.with(HashMap::clear);
    }

    pub fn is_consistent(&self) -> bool {
        let map_len = self.entries.read(HashMap::len);
        let queue_len = self.eviction_order.read(VecDeque::len);
        map_len == queue_len
    }
}

use std::collections::{HashMap, VecDeque};
use adamantium::{Actor, Bytes, Str};

#[derive(Clone, Debug)]
pub struct AssetCacheConfig {
    pub bucket_name: Str,
    pub max_assets: usize,
    pub max_blob_bytes: usize,
}

#[derive(Clone, Debug)]
pub struct AssetBlob {
    pub key: Str,
    pub content_type: Str,
    pub data: Bytes,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum AssetError {
    EmptyKey,
    BlobTooLarge { len: usize, max: usize },
}

#[derive(Clone, Copy, Debug)]
pub struct AssetCacheStats {
    pub entry_count: usize,
    pub queue_len: usize,
}

struct AssetCacheInner {
    entries: HashMap<Str, AssetBlob>,
    eviction_order: VecDeque<Str>,
}

impl AssetCacheInner {
    fn new(cap: usize) -> Self {
        Self {
            entries: HashMap::with_capacity(cap.min(256)),
            eviction_order: VecDeque::with_capacity(cap.min(256)),
        }
    }
}

pub struct AssetCache {
    config: AssetCacheConfig,
    inner: Actor<AssetCacheInner>,
}

impl AssetCache {
    pub fn new(config: AssetCacheConfig) -> Self {
        let cap = config.max_assets;
        Self {
            config,
            inner: Actor::new(AssetCacheInner::new(cap)),
        }
    }

    pub fn bucket_name(&self) -> &Str {
        &self.config.bucket_name
    }

    pub fn validate(&self, blob: &AssetBlob) -> Result<(), AssetError> {
        if blob.key.is_empty() {
            return Err(AssetError::EmptyKey);
        }
        if blob.data.len() > self.config.max_blob_bytes {
            return Err(AssetError::BlobTooLarge {
                len: blob.data.len(),
                max: self.config.max_blob_bytes,
            });
        }
        Ok(())
    }

    pub fn stats(&self) -> AssetCacheStats {
        self.inner.read(|state| AssetCacheStats {
            entry_count: state.entries.len(),
            queue_len: state.eviction_order.len(),
        })
    }

    pub fn get(&self, key: &str) -> Option<AssetBlob> {
        self.inner.read(|state| state.entries.get(key).cloned())
    }

    pub fn put(&self, blob: AssetBlob) -> Result<(), AssetError> {
        self.validate(&blob)?;
        let cap = self.config.max_assets;
        if cap == 0 {
            return Ok(());
        }
        let key = blob.key.clone();
        self.inner.with(|state| {
            if !state.entries.contains_key(&key) {
                while state.entries.len() >= cap {
                    let Some(old_key) = state.eviction_order.pop_front() else {
                        break;
                    };
                    state.entries.remove(&old_key);
                }
                state.eviction_order.push_back(key.clone());
            }
            state.entries.insert(key, blob);
        });
        Ok(())
    }

    pub fn remove(&self, key: &str) -> bool {
        self.inner.with(|state| {
            if state.entries.remove(key).is_some() {
                state.eviction_order.retain(|existing| existing.as_str() != key);
                true
            } else {
                false
            }
        })
    }

    pub fn clear(&self) {
        self.inner.with(|state| {
            state.entries.clear();
            state.eviction_order.clear();
        });
    }

    pub fn is_consistent(&self) -> bool {
        self.inner
            .read(|state| state.entries.len() == state.eviction_order.len())
    }
}

use std::sync::atomic::{AtomicUsize, Ordering};
use adamantium::{Actor, Str};

pub const SECTION_COUNT: usize = 8;

#[derive(Clone, Copy, Debug)]
pub struct SectionSeats {
    pub capacity: usize,
    pub reserved: usize,
}

impl SectionSeats {
    pub fn available(self) -> usize {
        self.capacity.saturating_sub(self.reserved)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum SeatError {
    InvalidSection(usize),
    ZeroSeats,
    SectionSoldOut { requested: usize, available: usize },
    VenueAtCapacity { requested: usize, available: usize },
    ReleaseExceedsReserved,
}

#[derive(Clone, Copy, Debug)]
pub struct VenueSummary {
    pub venue_capacity: usize,
    pub total_reserved: usize,
    pub section_sum: usize,
}

impl VenueSummary {
    pub fn remaining(self) -> usize {
        self.venue_capacity.saturating_sub(self.total_reserved)
    }
}

pub struct VenueAllocator {
    venue_name: Str,
    venue_capacity: usize,
    sections: Actor<[SectionSeats; SECTION_COUNT]>,
    total_reserved: AtomicUsize,
}

impl VenueAllocator {
    pub fn new(venue_name: Str, section_capacities: [usize; SECTION_COUNT]) -> Self {
        let mut sections = [SectionSeats {
            capacity: 0,
            reserved: 0,
        }; SECTION_COUNT];
        let mut total_capacity = 0usize;
        for (slot, cap) in sections.iter_mut().zip(section_capacities) {
            slot.capacity = cap;
            total_capacity = total_capacity.saturating_add(cap);
        }
        Self {
            venue_name,
            venue_capacity: total_capacity,
            sections: Actor::new(sections),
            total_reserved: AtomicUsize::new(0),
        }
    }

    pub fn venue_name(&self) -> &Str {
        &self.venue_name
    }

    pub fn section_available(&self, section: usize) -> Result<usize, SeatError> {
        if section >= SECTION_COUNT {
            return Err(SeatError::InvalidSection(section));
        }
        Ok(self.sections.read(|s| s[section].available()))
    }

    pub fn summary(&self) -> VenueSummary {
        let section_sum = self
            .sections
            .read(|s| s.iter().map(|sec| sec.reserved).sum());
        let total_reserved = self.total_reserved.load(Ordering::Acquire);
        VenueSummary {
            venue_capacity: self.venue_capacity,
            total_reserved,
            section_sum,
        }
    }

    pub fn reserve(&self, section: usize, count: usize) -> Result<usize, SeatError> {
        if section >= SECTION_COUNT {
            return Err(SeatError::InvalidSection(section));
        }
        if count == 0 {
            return Err(SeatError::ZeroSeats);
        }
        let current_total = self.total_reserved.load(Ordering::Acquire);
        if current_total.saturating_add(count) > self.venue_capacity {
            return Err(SeatError::VenueAtCapacity {
                requested: count,
                available: self.venue_capacity.saturating_sub(current_total),
            });
        }
        let remaining_in_section = self.sections.with(|s| {
            let avail = s[section].available();
            if avail < count {
                return Err(SeatError::SectionSoldOut {
                    requested: count,
                    available: avail,
                });
            }
            s[section].reserved += count;
            Ok(s[section].available())
        })?;
        self.total_reserved.fetch_add(count, Ordering::Release);
        Ok(remaining_in_section)
    }

    pub fn release(&self, section: usize, count: usize) -> Result<(), SeatError> {
        if section >= SECTION_COUNT {
            return Err(SeatError::InvalidSection(section));
        }
        if count == 0 {
            return Err(SeatError::ZeroSeats);
        }
        self.sections.with(|s| {
            if s[section].reserved < count {
                return Err(SeatError::ReleaseExceedsReserved);
            }
            s[section].reserved -= count;
            Ok(())
        })?;
        self.total_reserved.fetch_sub(count, Ordering::Release);
        Ok(())
    }

    pub fn audit_invariant(&self) -> bool {
        let sum: usize = self
            .sections
            .read(|s| s.iter().map(|sec| sec.reserved).sum());
        sum == self.total_reserved.load(Ordering::Acquire)
    }
}

