use std::sync::atomic::{AtomicU64, Ordering};
use adamantium::{Actor, Array, Str};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PolicyRule {
    pub prefix: Str,
    pub allow: bool,
}

#[derive(Clone, Debug)]
pub struct RouteDecision {
    pub epoch: u64,
    pub allowed: bool,
}

pub struct AccessPolicyRouter {
    service_name: Str,
    epoch: AtomicU64,
    rules: Actor<Array<PolicyRule>>,
}

impl AccessPolicyRouter {
    pub fn new(service_name: Str, initial_rules: Array<PolicyRule>) -> Self {
        Self {
            service_name,
            epoch: AtomicU64::new(1),
            rules: Actor::new(initial_rules),
        }
    }

    pub fn service_name(&self) -> &Str {
        &self.service_name
    }

    pub fn current_epoch(&self) -> u64 {
        self.epoch.load(Ordering::Acquire)
    }

    pub fn rule_count(&self) -> usize {
        self.rules.read(|r| r.len())
    }

    pub fn reload(&self, replacement: Array<PolicyRule>) -> u64 {
        let next_epoch = self.epoch.fetch_add(1, Ordering::AcqRel) + 1;
        self.rules.with(|r| {
            *r = replacement;
        });
        next_epoch
    }

    pub fn evaluate(&self, path: &str) -> RouteDecision {
        let epoch = self.epoch.load(Ordering::Acquire);
        let allowed = self.rules.read(|rules| {
            rules
                .iter()
                .find(|rule| path.starts_with(rule.prefix.as_str()))
                .is_some_and(|rule| rule.allow)
        });
        RouteDecision { epoch, allowed }
    }

    pub fn snapshot(&self) -> (u64, Array<PolicyRule>) {
        let epoch = self.epoch.load(Ordering::Acquire);
        let rules = self.rules.snapshot();
        (epoch, rules)
    }
}

