use std::collections::{HashMap, HashSet};
use adamantium::{Actor, Str};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct LeaseRecord {
    pub worker_id: u32,
    pub claimed_at_ms: u64,
    pub tag: Str,
}

#[derive(Clone, Copy, Debug)]
pub struct LeaseCounts {
    pub active_set_len: usize,
    pub owner_map_len: usize,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum LeaseError {
    AlreadyClaimed(u64),
    NotOwner { job_id: u64, worker_id: u32 },
}

pub struct JobLeaseRegistry {
    pool_name: Str,
    active_jobs: Actor<HashSet<u64>>,
    lease_owners: Actor<HashMap<u64, LeaseRecord>>,
}

impl JobLeaseRegistry {
    pub fn new(pool_name: Str) -> Self {
        Self {
            pool_name,
            active_jobs: Actor::new(HashSet::new()),
            lease_owners: Actor::new(HashMap::new()),
        }
    }

    pub fn pool_name(&self) -> &Str {
        &self.pool_name
    }

    pub fn counts(&self) -> LeaseCounts {
        LeaseCounts {
            active_set_len: self.active_jobs.read(HashSet::len),
            owner_map_len: self.lease_owners.read(HashMap::len),
        }
    }

    pub fn owner_of(&self, job_id: u64) -> Option<LeaseRecord> {
        self.lease_owners.read(|m| m.get(&job_id).cloned())
    }

    pub fn acquire(
        &self,
        job_id: u64,
        worker_id: u32,
        now_ms: u64,
        tag: Str,
    ) -> Result<(), LeaseError> {
        let inserted = self.active_jobs.with(|set| set.insert(job_id));
        if !inserted {
            return Err(LeaseError::AlreadyClaimed(job_id));
        }
        self.lease_owners.with(|owners| {
            owners.insert(
                job_id,
                LeaseRecord {
                    worker_id,
                    claimed_at_ms: now_ms,
                    tag,
                },
            );
        });
        Ok(())
    }

    pub fn release(&self, job_id: u64, worker_id: u32) -> Result<(), LeaseError> {
        let is_owner = self
            .lease_owners
            .read(|owners| owners.get(&job_id).is_some_and(|r| r.worker_id == worker_id));
        if !is_owner {
            return Err(LeaseError::NotOwner { job_id, worker_id });
        }
        self.lease_owners.with(|owners| {
            owners.remove(&job_id);
        });
        self.active_jobs.with(|set| {
            set.remove(&job_id);
        });
        Ok(())
    }
}

