    total_claimed: u64,
    total_released: u64,
}

pub struct JobLeaseRegistry {
    pool_name: Str,
    state: Actor<LeaseState>,
}

impl JobLeaseRegistry {
    pub fn new(pool_name: Str) -> Self {
        Self {
            pool_name,
            state: Actor::new(LeaseState {
                owners: HashMap::new(),
                total_claimed: 0,
                total_released: 0,
            }),
        }
    }

    pub fn pool_name(&self) -> &Str {
        &self.pool_name
    }

    pub fn counts(&self) -> LeaseCounts {
        self.state.read(|s| LeaseCounts {
            active_leases: s.owners.len(),
            total_claimed: s.total_claimed,
            total_released: s.total_released,
        })
    }

    pub fn owner_of(&self, job_id: u64) -> Option<LeaseRecord> {
        self.state.read(|s| s.owners.get(&job_id).cloned())
    }

    pub fn acquire(
        &self,
        job_id: u64,
        worker_id: u32,
        now_ms: u64,
        tag: Str,
    ) -> Result<(), LeaseError> {
        self.state.with(|s| {
            if s.owners.contains_key(&job_id) {
                return Err(LeaseError::AlreadyClaimed(job_id));
            }
            s.owners.insert(
                job_id,
                LeaseRecord {
                    worker_id,
                    claimed_at_ms: now_ms,
                    tag,
                },
            );
            s.total_claimed += 1;
            Ok(())
        })
    }

    pub fn release(&self, job_id: u64, worker_id: u32) -> Result<(), LeaseError> {
        self.state.with(|s| {
            let is_owner = s
                .owners
                .get(&job_id)
                .is_some_and(|r| r.worker_id == worker_id);
            if !is_owner {
                return Err(LeaseError::NotOwner { job_id, worker_id });
            }
            s.owners.remove(&job_id);
            s.total_released += 1;
            Ok(())
        })
    }

    pub fn release_all_for_worker(&self, worker_id: u32) -> usize {
        self.state.with(|s| {
            let before = s.owners.len();
            s.owners.retain(|_, record| record.worker_id != worker_id);
            let removed = before.saturating_sub(s.owners.len());
            s.total_released += removed as u64;
            removed
        })
    }
}

use std::sync::atomic::{AtomicU64, Ordering};
use adamantium::Str;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum WindowError {
    InvertedRange { low: u64, high: u64 },
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct WindowBounds {
    pub low: u64,
    pub high: u64,
}

impl WindowBounds {
    pub fn width(self) -> u64 {
        self.high.saturating_sub(self.low)
    }

    pub fn contains(self, value: u64) -> bool {
        value >= self.low && value <= self.high
    }
}

pub struct RetentionWindow {
    stream_name: Str,
    low: AtomicU64,
    high: AtomicU64,
}

impl RetentionWindow {
    pub fn new(stream_name: Str, low: u64, high: u64) -> Result<Self, WindowError> {
        if low > high {
            return Err(WindowError::InvertedRange { low, high });
        }
        Ok(Self {
            stream_name,
            low: AtomicU64::new(low),
            high: AtomicU64::new(high),
        })
    }

    pub fn stream_name(&self) -> &Str {
        &self.stream_name
    }

    pub fn set_bounds(&self, low: u64, high: u64) -> Result<(), WindowError> {
        if low > high {
            return Err(WindowError::InvertedRange { low, high });
        }
        self.low.store(low, Ordering::Release);
        self.high.store(high, Ordering::Release);
        Ok(())
    }

    pub fn snapshot(&self) -> WindowBounds {
        let low = self.low.load(Ordering::Acquire);
        let high = self.high.load(Ordering::Acquire);
        WindowBounds { low, high }
    }

    pub fn contains(&self, seq: u64) -> bool {
        self.snapshot().contains(seq)
    }
}

