use std::sync::{Arc, Mutex};
use adamantium::Str;

pub const SLOT_COUNT: usize = 16;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum SlotError {
    OutOfRange(usize),
    InsufficientStock { requested: u32, available: u32 },
}

#[derive(Clone, Copy, Debug)]
pub struct SlotTotals {
    pub available: u32,
    pub reserved: u32,
}

pub struct SlotInventory {
    warehouse: Str,
    available: Arc<Mutex<[u32; SLOT_COUNT]>>,
    reserved: Arc<Mutex<[u32; SLOT_COUNT]>>,
}

impl SlotInventory {
    pub fn new(warehouse: Str, initial_stock: [u32; SLOT_COUNT]) -> Self {
        Self {
            warehouse,
            available: Arc::new(Mutex::new(initial_stock)),
            reserved: Arc::new(Mutex::new([0; SLOT_COUNT])),
        }
    }

    pub fn warehouse(&self) -> &Str {
        &self.warehouse
    }

    pub fn reserve(&self, slot: usize, qty: u32) -> Result<(), SlotError> {
        if slot >= SLOT_COUNT {
            return Err(SlotError::OutOfRange(slot));
        }
        {
            let mut avail = self.available.lock().unwrap();
            if avail[slot] < qty {
                return Err(SlotError::InsufficientStock {
                    requested: qty,
                    available: avail[slot],
                });
            }
            avail[slot] -= qty;
        }
        let mut res = self.reserved.lock().unwrap();
        res[slot] += qty;
        Ok(())
    }

    pub fn totals(&self, slot: usize) -> Result<SlotTotals, SlotError> {
        if slot >= SLOT_COUNT {
            return Err(SlotError::OutOfRange(slot));
        }
        let available = self.available.lock().unwrap()[slot];
        let reserved = self.reserved.lock().unwrap()[slot];
        Ok(SlotTotals {
            available,
            reserved,
        })
    }
}

use std::cell::RefCell;
use std::rc::Rc;

pub const BUCKETS: usize = 8;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum LedgerError {
    BadBucket(usize),
    InsufficientBalance,
}

#[derive(Clone, Copy, Debug)]
pub struct BookTotals {
    pub sum_buckets: u64,
    pub total_balance: u64,
}

struct BookState {
    buckets: [u64; BUCKETS],
    total_balance: u64,
}

pub struct LocalBookkeeper {
    state: Rc<RefCell<BookState>>,
}

impl LocalBookkeeper {
    pub fn new(initial: [u64; BUCKETS]) -> Self {
        let total_balance = initial.iter().copied().sum();
        Self {
            state: Rc::new(RefCell::new(BookState {
                buckets: initial,
                total_balance,
            })),
        }
    }

    pub fn credit(&self, bucket: usize, amount: u64) -> Result<(), LedgerError> {
        if bucket >= BUCKETS {
            return Err(LedgerError::BadBucket(bucket));
        }
        let mut state = self.state.borrow_mut();
        state.buckets[bucket] += amount;
        state.total_balance += amount;
        Ok(())
    }

    pub fn debit(&self, bucket: usize, amount: u64) -> Result<(), LedgerError> {
        if bucket >= BUCKETS {
            return Err(LedgerError::BadBucket(bucket));
        }
        let mut state = self.state.borrow_mut();
        if state.buckets[bucket] < amount {
            return Err(LedgerError::InsufficientBalance);
        }
        state.buckets[bucket] -= amount;
        state.total_balance -= amount;
        Ok(())
    }

    pub fn totals(&self) -> BookTotals {
        let state = self.state.borrow();
        BookTotals {
            sum_buckets: state.buckets.iter().copied().sum(),
            total_balance: state.total_balance,
        }
    }
}

