}

impl ShardBridge {
    pub fn new(
        config: SyncConfig,
        primary: Actor<PrimaryShard>,
        secondary: Actor<SecondaryShard>,
    ) -> Self {
        Self {
            config,
            primary,
            secondary,
        }
    }

