use adamantium::{Actor, Str};
use std::collections::{HashMap, VecDeque};

#[derive(Clone, Debug)]
pub struct RunnerConfig {
    pub pool_name: Str,
    pub max_tracked_jobs: usize,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum JobPhase {
    Queued,
    Running,
    Completed,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum RunnerError {
    NotFound(u64),
    NotQueued(u64),
    QueueFull { max_tracked_jobs: usize },
    RemoteFailed(Str),
}

#[derive(Clone, Debug)]
struct JobEntry {
    name: Str,
    phase: JobPhase,
    attempts: u32,
}

#[derive(Clone, Copy, Debug)]
pub struct RunnerStats {
    pub total: usize,
    pub running: usize,
    pub completed: u64,
}

struct RunnerState {
    jobs: HashMap<u64, JobEntry>,
    order: VecDeque<u64>,
    completed: u64,
}

impl RunnerState {
    fn new(cap: usize) -> Self {
        Self {
            jobs: HashMap::with_capacity(cap),
            order: VecDeque::with_capacity(cap),
            completed: 0,
        }
    }

    fn insert_bounded(
        &mut self,
        id: u64,
        name: Str,
        max_tracked: usize,
    ) -> Result<(), RunnerError> {
        let is_new = !self.jobs.contains_key(&id);
        if is_new && self.jobs.len() >= max_tracked {
            let mut evicted = false;
            for _ in 0..self.order.len() {
                if let Some(oldest) = self.order.pop_front() {
                    if self
                        .jobs
                        .get(&oldest)
                        .is_some_and(|j| j.phase == JobPhase::Completed)
                    {
                        self.jobs.remove(&oldest);
                        evicted = true;
                        break;
                    }
                    self.order.push_back(oldest);
                }
            }
            if !evicted {
                return Err(RunnerError::QueueFull {
                    max_tracked_jobs: max_tracked,
                });
            }
        }
        self.jobs.insert(
            id,
            JobEntry {
                name,
                phase: JobPhase::Queued,
                attempts: 0,
            },
        );
        if is_new {
            self.order.push_back(id);
        }
        Ok(())
    }
}

pub struct TaskRunner {
    config: RunnerConfig,
    state: Actor<RunnerState>,
}

impl TaskRunner {
    pub fn new(config: RunnerConfig) -> Self {
        let cap = config.max_tracked_jobs.min(256);
        Self {
            config,
            state: Actor::new(RunnerState::new(cap)),
        }
    }

    pub fn stats(&self) -> RunnerStats {
        self.state.read(|s| RunnerStats {
            total: s.jobs.len(),
            running: s
                .jobs
                .values()
                .filter(|j| j.phase == JobPhase::Running)
                .count(),
            completed: s.completed,
        })
    }

    pub fn enqueue(&self, id: u64, name: Str) -> Result<(), RunnerError> {
        let max_tracked = self.config.max_tracked_jobs;
        self.state.with(|s| s.insert_bounded(id, name, max_tracked))
    }

    pub async fn execute(&self, id: u64) -> Result<(), RunnerError> {
        let job_name = self.state.with(|s| {
            let entry = s.jobs.get_mut(&id).ok_or(RunnerError::NotFound(id))?;
            if entry.phase != JobPhase::Queued {
                return Err(RunnerError::NotQueued(id));
            }
            entry.phase = JobPhase::Running;
            entry.attempts += 1;
            Ok(entry.name.clone())
        })?;

        invoke_worker_rpc(&self.config.pool_name, id, &job_name)
            .await
            .map_err(RunnerError::RemoteFailed)?;

        self.state.with(|s| {
            if let Some(entry) = s.jobs.get_mut(&id) {
                entry.phase = JobPhase::Completed;
                s.completed += 1;
            }
        });
        Ok(())
    }
}

