            }
            entry.phase = JobPhase::Running;
            entry.attempts += 1;
            Ok(entry.name.clone())
        })?;
        let mut guard = RunningJobGuard {
            state: self.state.clone(),
            id,
            finished: false,
        };

        invoke_worker_rpc(&self.config.pool_name, id, &job_name)
            .await
            .map_err(RunnerError::RemoteFailed)?;

        self.state.with(|s| {
            if let Some(entry) = s.jobs.get_mut(&id) {
