use adamantium::{AsyncActor, Bytes, Reply, Sender, Str, Tasks};
use std::collections::VecDeque;

#[derive(Clone, Debug)]
pub struct ForwardConfig {
    pub stream: Str,
    pub max_buffered: usize,
}

#[derive(Clone, Debug)]
pub struct OutboundRecord {
    pub seq: u64,
    pub stream: Str,
    pub body: Bytes,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ForwardError {
    BufferFull { max_buffered: usize },
    DownstreamClosed,
}

#[derive(Clone, Copy, Debug)]
pub struct ForwardStats {
    pub buffered: usize,
    pub delivered: u64,
    pub dropped_on_full: u64,
}

enum ForwardCmd {
    Push {
        seq: u64,
        body: Bytes,
        reply: Reply<Result<(), ForwardError>>,
    },
    DeliverNext {
        tx: Sender<OutboundRecord>,
        reply: Reply<Result<bool, ForwardError>>,
    },
    Stats {
        reply: Reply<ForwardStats>,
    },
}

struct ForwardState {
    config: ForwardConfig,
    buffer: VecDeque<OutboundRecord>,
    delivered: u64,
    dropped_on_full: u64,
}

pub fn spawn_record_forwarder(
    tasks: &mut Tasks<ForwardError>,
    config: ForwardConfig,
) -> AsyncActor<ForwardCmd> {
    let cap = config.max_buffered.min(256);
    let initial = ForwardState {
        config,
        buffer: VecDeque::with_capacity(cap),
        delivered: 0,
        dropped_on_full: 0,
    };
    AsyncActor::new(tasks, initial, 64, |state, cmd| {
        Box::pin(async move {
            match cmd {
                ForwardCmd::Push { seq, body, reply } => {
                    let outcome = if state.buffer.len() >= state.config.max_buffered {
                        state.dropped_on_full += 1;
                        Err(ForwardError::BufferFull {
                            max_buffered: state.config.max_buffered,
                        })
                    } else {
                        state.buffer.push_back(OutboundRecord {
                            seq,
                            stream: state.config.stream.clone(),
                            body,
                        });
                        Ok(())
                    };
                    let _ = reply.send(outcome);
                }
                ForwardCmd::DeliverNext { tx, reply } => {
                    let outcome = if let Some(record) = state.buffer.pop_front() {
                        match tx.send(record).await {
                            Ok(()) => {
                                state.delivered += 1;
                                Ok(true)
                            }
                            Err(_) => Err(ForwardError::DownstreamClosed),
                        }
                    } else {
                        Ok(false)
                    };
                    let _ = reply.send(outcome);
                }
                ForwardCmd::Stats { reply } => {
                    let _ = reply.send(ForwardStats {
                        buffered: state.buffer.len(),
                        delivered: state.delivered,
                        dropped_on_full: state.dropped_on_full,
                    });
                }
            }
            Ok(())
        })
    })
}

