    completed_rollouts: u64,
}

impl DeployState {
    fn new(max_releases: usize, max_history: usize) -> Self {
        Self {
            releases: HashMap::with_capacity(max_releases.min(128)),
            eviction_order: VecDeque::with_capacity(max_releases.min(128)),
            history: VecDeque::with_capacity(max_history.min(128)),
            completed_rollouts: 0,
        }
    }

    fn push_event(&mut self, event: DeployEvent, max_history: usize) {
        if max_history == 0 {
            return;
        }
        if self.history.len() >= max_history {
            self.history.pop_front();
        }
        self.history.push_back(event);
    }

    fn register_release(
        &mut self,
        spec: ReleaseSpec,
        max_releases: usize,
    ) -> Result<(), DeployError> {
        let id = spec.release_id;
        let is_new = !self.releases.contains_key(&id);
        if is_new && self.releases.len() >= max_releases {
            let mut evicted = false;
            for _ in 0..self.eviction_order.len() {
                if let Some(oldest) = self.eviction_order.pop_front() {
                    if self.releases.get(&oldest).is_some_and(|r| {
                        matches!(r.status, DeployStatus::Active | DeployStatus::Failed)
                    }) {
                        self.releases.remove(&oldest);
                        evicted = true;
                        break;
                    }
                    self.eviction_order.push_back(oldest);
                }
            }
            if !evicted {
                return Err(DeployError::ReleaseLimitReached { max_releases });
            }
        }
        self.releases.insert(
            id,
            ReleaseRecord {
                spec,
                status: DeployStatus::Queued,
                attempts: 0,
            },
        );
        if is_new {
            self.eviction_order.push_back(id);
        }
