pub struct DeployController {
    config: DeployConfig,
    state: Actor<DeployState>,
}

impl DeployController {
    pub fn new(config: DeployConfig) -> Self {
        let max_releases = config.max_releases;
        let max_history = config.max_history;
        Self {
            config,
            state: Actor::new(DeployState::new(max_releases, max_history)),
        }
    }

    pub fn cluster_name(&self) -> &Str {
        &self.config.cluster
    }

    pub fn summary(&self) -> DeploySummary {
        self.state.read(|s| DeploySummary {
            tracked: s.releases.len(),
            deploying: s
                .releases
                .values()
                .filter(|r| r.status == DeployStatus::Deploying)
                .count(),
            active: s
                .releases
                .values()
                .filter(|r| r.status == DeployStatus::Active)
                .count(),
            completed_rollouts: s.completed_rollouts,
        })
    }

    pub fn recent_events(&self, limit: usize) -> Vec<DeployEvent> {
        self.state.read(|s| {
            let skip = s.history.len().saturating_sub(limit);
            s.history.iter().skip(skip).cloned().collect()
        })
    }

    pub fn register(&self, spec: ReleaseSpec) -> Result<(), DeployError> {
        let max_releases = self.config.max_releases;
        self.state.with(|s| s.register_release(spec, max_releases))
    }

    pub async fn rollout(&self, release_id: u64) -> Result<(), DeployError> {
        let max_history = self.config.max_history;
        let (spec, attempt) = self.state.with(|s| {
            let record = s
                .releases
                .get_mut(&release_id)
                .ok_or(DeployError::UnknownRelease(release_id))?;
            if record.status == DeployStatus::Deploying {
                return Err(DeployError::AlreadyInProgress(release_id));
            }
            record.status = DeployStatus::Deploying;
            record.attempts += 1;
            let attempt = record.attempts;
            let spec = record.spec.clone();
            s.push_event(
                DeployEvent {
                    release_id,
                    status: DeployStatus::Deploying,
                    attempt,
                },
                max_history,
            );
            Ok((spec, attempt))
        })?;

        apply_cluster_manifest(
            &self.config.cluster,
            spec.release_id,
            &spec.image_digest,
            spec.target_replicas,
        )
        .await
        .map_err(DeployError::RolloutRejected)?;

        self.state.with(|s| {
            if let Some(record) = s.releases.get_mut(&release_id) {
                record.status = DeployStatus::Active;
                s.completed_rollouts += 1;
                s.push_event(
                    DeployEvent {
                        release_id,
                        status: DeployStatus::Active,
                        attempt,
                    },
                    max_history,
                );
            }
        });
        Ok(())
    }
}

