struct RebuildGuard {
    state: Actor<IndexState>,
    previous_phase: IndexPhase,
    armed: bool,
}

impl RebuildGuard {
    fn disarm(&mut self) {
        self.armed = false;
    }
}

impl Drop for RebuildGuard {
    fn drop(&mut self) {
        if self.armed {
            let restore = self.previous_phase;
            self.state.with(|s| {
                s.phase = restore;
                s.active_rebuilds = s.active_rebuilds.saturating_sub(1);
            });
        }
    }
}

