            stored_snapshots: s.snapshots.len(),
        })
    }

    pub async fn rebuild_from_primary(&self, target_generation: u64) -> Result<u64, IndexError> {
        let previous_phase = self.state.with(|s| {
            if s.phase == IndexPhase::Rebuilding {
                return Err(IndexError::AlreadyRebuilding);
            }
            let prev = s.phase;
            s.phase = IndexPhase::Rebuilding;
            s.active_rebuilds += 1;
            Ok(prev)
        })?;
        let mut guard = RebuildGuard {
            state: self.state.clone(),
            previous_phase,
            armed: true,
        };

        stream_segment_snapshot(&self.config.index_name, target_generation)
            .await
            .map_err(IndexError::SnapshotStreamFailed)?;

        let cap = self.config.max_snapshots;
        let committed_gen = self.state.with(|s| {
            s.generation = target_generation;
            s.phase = IndexPhase::Ready;
            s.active_rebuilds = s.active_rebuilds.saturating_sub(1);
            s.record_snapshot(target_generation, cap);
            s.generation
        });
        guard.disarm();
        Ok(committed_gen)
    }
