}

impl CompactionTable {
    fn new(cap: usize) -> Self {
        Self {
            in_progress: HashSet::with_capacity(cap.min(64)),
            completed_runs: 0,
            reclaimed_bytes: 0,
        }
    }
}

pub struct ShardCompactor {
    config: CompactionConfig,
    table: Actor<CompactionTable>,
}

impl ShardCompactor {
    pub fn new(config: CompactionConfig) -> Self {
        let cap = config.max_concurrent_shards;
        Self {
            config,
            table: Actor::new(CompactionTable::new(cap)),
        }
    }

    pub fn volume_name(&self) -> &Str {
        &self.config.volume_name
    }

    pub fn is_compacting(&self, shard_id: u64) -> bool {
        self.table.read(|t| t.in_progress.contains(&shard_id))
    }

    pub fn stats(&self) -> CompactionStats {
        self.table.read(|t| CompactionStats {
            in_progress: t.in_progress.len(),
            completed_runs: t.completed_runs,
            reclaimed_bytes: t.reclaimed_bytes,
        })
    }

    pub async fn compact_shard(&self, shard_id: u64) -> Result<u64, CompactionError> {
        let limit = self.config.max_concurrent_shards;
        self.table.with(|t| {
            if t.in_progress.contains(&shard_id) {
                return Err(CompactionError::ShardBusy(shard_id));
            }
            if t.in_progress.len() >= limit {
                return Err(CompactionError::ConcurrencyLimitReached { limit });
            }
            t.in_progress.insert(shard_id);
            Ok(())
        })?;

        let reclaimed = rewrite_shard_segments(&self.config.volume_name, shard_id)
            .await
            .map_err(CompactionError::IoFailed)?;

        self.table.with(|t| {
            t.in_progress.remove(&shard_id);
            t.completed_runs += 1;
            t.reclaimed_bytes += reclaimed;
        });
        Ok(reclaimed)
    }
}

