    fn validate_and_push(&mut self, event: WebhookEvent) -> Result<(), WebhookError> {
        if event.body.len() > self.config.max_payload_bytes {
            return Err(WebhookError::PayloadTooLarge {
                len: event.body.len(),
                max: self.config.max_payload_bytes,
            });
        }
        if self.queue.len() >= self.config.max_queued {
            self.rejected_on_full += 1;
            return Err(WebhookError::QueueFull {
                max_queued: self.config.max_queued,
            });
        }
        self.queue.push_back(event);
        Ok(())
    }

    fn purge_topic(&mut self, topic: &Str) -> usize {
        let before = self.queue.len();
        self.queue.retain(|ev| &ev.topic != topic);
        before - self.queue.len()
    }

    fn snapshot_stats(&self) -> WebhookStats {
        WebhookStats {
            queued: self.queue.len(),
            delivered: self.delivered,
            delivery_errors: self.delivery_errors,
            rejected_on_full: self.rejected_on_full,
