struct FlusherState {
    config: FlusherConfig,
    pending: VecDeque<MetricSample>,
    uploaded_samples: u64,
    evicted_oldest: u64,
}

impl FlusherState {
    fn push_bounded(&mut self, sample: MetricSample) {
        if self.config.max_pending == 0 {
            return;
        }
        if self.pending.len() >= self.config.max_pending {
            self.pending.pop_front();
            self.evicted_oldest += 1;
        }
        self.pending.push_back(sample);
    }
}

pub fn spawn_telemetry_flusher(
    tasks: &mut Tasks<FlusherError>,
    config: FlusherConfig,
) -> AsyncActor<FlusherCmd> {
