        Box::pin(async move {
            match cmd {
                FlusherCmd::Record { sample } => {
                    state.push_bounded(sample);
                }
                FlusherCmd::FlushBatch { reply } => {
                    let count = state.pending.len().min(state.config.max_batch);
                    let outcome = if count == 0 {
                        Ok(0)
                    } else {
                        let batch: Vec<MetricSample> = state.pending.drain(..count).collect();
                        match upload_metric_batch(&state.config.sink_url, &batch).await {
