    ZeroAmount,
    AccountNotFound(u64),
    AccountLimitReached { max_accounts: usize },
    InsufficientFunds { available: u64, requested: u64 },
    GatewayDeclined(Str),
}

#[derive(Clone, Copy, Debug)]
pub struct AccountBalance {
    pub available: u64,
    pub held: u64,
}

#[derive(Clone, Debug)]
pub struct SettlementReceipt {
    pub account_id: u64,
    pub amount: u64,
    pub reference: Str,
}

struct EscrowLedger {
    accounts: HashMap<u64, AccountBalance>,
    receipts: VecDeque<SettlementReceipt>,
    settled_volume: u64,
}

impl EscrowLedger {
    fn new(max_accounts: usize, max_receipts: usize) -> Self {
        Self {
            accounts: HashMap::with_capacity(max_accounts.min(128)),
            receipts: VecDeque::with_capacity(max_receipts.min(128)),
            settled_volume: 0,
        }
    }

    fn record_receipt(&mut self, receipt: SettlementReceipt, max_receipts: usize) {
        if max_receipts == 0 {
            return;
        }
        if self.receipts.len() >= max_receipts {
            self.receipts.pop_front();
        }
        self.receipts.push_back(receipt);
    }
}

pub struct EscrowService {
    config: EscrowConfig,
    ledger: Actor<EscrowLedger>,
}

impl EscrowService {
    pub fn new(config: EscrowConfig) -> Self {
        let max_accounts = config.max_accounts;
        let max_receipts = config.max_receipts;
        Self {
            config,
            ledger: Actor::new(EscrowLedger::new(max_accounts, max_receipts)),
        }
    }

    pub fn currency(&self) -> &Str {
        &self.config.currency
    }

    pub fn open_account(&self, account_id: u64, initial_balance: u64) -> Result<(), EscrowError> {
        let max_accounts = self.config.max_accounts;
        self.ledger.with(|l| {
            if !l.accounts.contains_key(&account_id) && l.accounts.len() >= max_accounts {
                return Err(EscrowError::AccountLimitReached { max_accounts });
            }
            l.accounts.insert(
                account_id,
                AccountBalance {
                    available: initial_balance,
                    held: 0,
                },
            );
            Ok(())
        })
    }

    pub fn balance(&self, account_id: u64) -> Option<AccountBalance> {
        self.ledger.read(|l| l.accounts.get(&account_id).copied())
    }

    pub fn recent_receipts(&self, limit: usize) -> Vec<SettlementReceipt> {
        self.ledger.read(|l| {
            let skip = l.receipts.len().saturating_sub(limit);
            l.receipts.iter().skip(skip).cloned().collect()
        })
    }

    pub fn settled_volume(&self) -> u64 {
        self.ledger.read(|l| l.settled_volume)
    }

    pub async fn settle_payout(
        &self,
        account_id: u64,
        amount: u64,
        reference: Str,
    ) -> Result<AccountBalance, EscrowError> {
        if amount == 0 {
            return Err(EscrowError::ZeroAmount);
        }

        authorize_settlement(&self.config.currency, account_id, amount, &reference)
            .await
            .map_err(EscrowError::GatewayDeclined)?;

        let max_receipts = self.config.max_receipts;
        let updated = self.ledger.with(|l| {
            let acct = l
                .accounts
                .get_mut(&account_id)
                .ok_or(EscrowError::AccountNotFound(account_id))?;
            if acct.available < amount {
                return Err(EscrowError::InsufficientFunds {
                    available: acct.available,
                    requested: amount,
                });
            }
            acct.available -= amount;
            let balance = *acct;
            l.settled_volume = l.settled_volume.saturating_add(amount);
            l.record_receipt(
                SettlementReceipt {
                    account_id,
                    amount,
                    reference,
                },
                max_receipts,
            );
            Ok(balance)
        })?;
        Ok(updated)
    }
}

use adamantium::{Actor, Str};

#[derive(Clone, Debug)]
pub struct GatewayConfig {
    pub listener_name: Str,
    pub max_active_handshakes: usize,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum HandshakeError {
    Overloaded { max_active: usize },
    TlsRejected(Str),
}

#[derive(Clone, Copy, Debug)]
pub struct GatewayStats {
    pub active_handshakes: usize,
    pub total_attempts: u64,
    pub completed_handshakes: u64,
    pub last_attempt_ms: u64,
}

struct GatewayState {
    active_handshakes: usize,
    total_attempts: u64,
    completed_handshakes: u64,
    last_attempt_ms: u64,
}

pub struct SessionGateway {
    config: GatewayConfig,
    state: Actor<GatewayState>,
}

impl SessionGateway {
    pub fn new(config: GatewayConfig) -> Self {
        Self {
            config,
            state: Actor::new(GatewayState {
                active_handshakes: 0,
                total_attempts: 0,
                completed_handshakes: 0,
                last_attempt_ms: 0,
            }),
        }
    }

    pub fn listener_name(&self) -> &Str {
        &self.config.listener_name
    }

    pub fn stats(&self) -> GatewayStats {
        self.state.read(|s| GatewayStats {
            active_handshakes: s.active_handshakes,
            total_attempts: s.total_attempts,
            completed_handshakes: s.completed_handshakes,
            last_attempt_ms: s.last_attempt_ms,
        })
    }

    pub async fn accept_peer(&self, peer_id: u64, now_ms: u64) -> Result<u64, HandshakeError> {
        let max_active = self.config.max_active_handshakes;
        self.state.with(|s| {
            if s.active_handshakes >= max_active {
                return Err(HandshakeError::Overloaded { max_active });
            }
            s.active_handshakes += 1;
            s.total_attempts += 1;
            s.last_attempt_ms = now_ms;
            Ok(())
        })?;

        let session_id = negotiate_tls_session(&self.config.listener_name, peer_id)
            .await
            .map_err(HandshakeError::TlsRejected)?;

        self.state.with(|s| {
            s.active_handshakes = s.active_handshakes.saturating_sub(1);
            s.completed_handshakes += 1;
        });
        Ok(session_id)
    }
}

