use adamantium::{Actor, Bytes, Str};
use std::time::Duration;

#[derive(Clone, Debug)]
pub struct PoolConfig {
    pub backend: Str,
    pub max_slots: usize,
    pub request_timeout: Duration,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum PoolError {
    NoFreeSlots { max_slots: usize },
    TimedOut,
    BackendFailed(Str),
}

#[derive(Clone, Copy, Debug)]
pub struct PoolStats {
    pub reserved_slots: usize,
    pub completed_calls: u64,
}

struct PoolState {
    reserved_slots: usize,
    completed_calls: u64,
}

pub struct WorkerPool {
    config: PoolConfig,
    state: Actor<PoolState>,
}

impl WorkerPool {
    pub fn new(config: PoolConfig) -> Self {
        Self {
            config,
            state: Actor::new(PoolState {
                reserved_slots: 0,
                completed_calls: 0,
            }),
        }
    }

    pub fn backend(&self) -> &Str {
        &self.config.backend
    }

    pub fn stats(&self) -> PoolStats {
        self.state.read(|s| PoolStats {
            reserved_slots: s.reserved_slots,
            completed_calls: s.completed_calls,
        })
    }

    pub async fn run_rpc(&self, payload: Bytes) -> Result<Bytes, PoolError> {
        let max_slots = self.config.max_slots;
        self.state.with(|s| {
            if s.reserved_slots >= max_slots {
                return Err(PoolError::NoFreeSlots { max_slots });
            }
            s.reserved_slots += 1;
            Ok(())
        })?;

        let response = tokio::time::timeout(
            self.config.request_timeout,
            send_backend_rpc(&self.config.backend, payload),
        )
        .await
        .map_err(|_| PoolError::TimedOut)?
        .map_err(PoolError::BackendFailed)?;

        self.state.with(|s| {
            s.reserved_slots = s.reserved_slots.saturating_sub(1);
            s.completed_calls += 1;
        });
        Ok(response)
    }
}

use adamantium::{Actor, Str};
use std::time::Duration;

#[derive(Clone, Debug)]
pub struct SyncConfig {
    pub replica_addr: Str,
    pub sync_deadline: Duration,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum SyncError {
    SyncAlreadyRunning,
    DeadlineExceeded,
    Transport(Str),
}

#[derive(Clone, Copy, Debug)]
pub struct SyncStats {
    pub syncing: bool,
    pub synced_batches: u64,
    pub last_offset: u64,
}

struct ReplicaState {
    syncing: bool,
    synced_batches: u64,
    last_offset: u64,
}

pub struct ReplicaSync {
    config: SyncConfig,
    state: Actor<ReplicaState>,
}

impl ReplicaSync {
    pub fn new(config: SyncConfig) -> Self {
        Self {
            config,
            state: Actor::new(ReplicaState {
                syncing: false,
                synced_batches: 0,
                last_offset: 0,
            }),
        }
    }

    pub fn stats(&self) -> SyncStats {
        self.state.read(|s| SyncStats {
            syncing: s.syncing,
            synced_batches: s.synced_batches,
            last_offset: s.last_offset,
        })
    }

    pub async fn pull_delta(&self) -> Result<u64, SyncError> {
        let from_offset = self.state.with(|s| {
            if s.syncing {
                return Err(SyncError::SyncAlreadyRunning);
            }
            s.syncing = true;
            Ok(s.last_offset)
        })?;

        let next_offset = tokio::select! {
            res = fetch_replica_delta(&self.config.replica_addr, from_offset) => {
                res.map_err(SyncError::Transport)?
            }
            () = tokio::time::sleep(self.config.sync_deadline) => {
                return Err(SyncError::DeadlineExceeded);
            }
        };

        self.state.with(|s| {
            s.syncing = false;
            s.synced_batches += 1;
            s.last_offset = next_offset;
        });
        Ok(next_offset)
    }
}

