use adamantium::{Actor, Str};
use std::time::Duration;

#[derive(Clone, Debug)]
pub struct ProbeConfig {
    pub upstream: Str,
    pub timeout: Duration,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ProbeError {
    AlreadyProbing,
    TimedOut,
    Failed(Str),
}

#[derive(Clone, Copy, Debug)]
pub struct ProbeStats {
    pub probing: bool,
    pub succeeded: u64,
    pub last_rtt_ms: u64,
}

struct ProbeState {
    probing: bool,
    succeeded: u64,
    last_rtt_ms: u64,
}

struct ProbeGuard {
    state: Actor<ProbeState>,
}

impl Drop for ProbeGuard {
    fn drop(&mut self) {
        self.state.with(|s| {
            s.probing = false;
        });
    }
}

pub struct UpstreamProber {
    config: ProbeConfig,
    state: Actor<ProbeState>,
}

impl UpstreamProber {
    pub fn new(config: ProbeConfig) -> Self {
        Self {
            config,
            state: Actor::new(ProbeState {
                probing: false,
                succeeded: 0,
                last_rtt_ms: 0,
            }),
        }
    }

    pub fn stats(&self) -> ProbeStats {
        self.state.read(|s| ProbeStats {
            probing: s.probing,
            succeeded: s.succeeded,
            last_rtt_ms: s.last_rtt_ms,
        })
    }

    pub async fn run_probe(&self) -> Result<u64, ProbeError> {
        self.state.with(|s| {
            if s.probing {
                return Err(ProbeError::AlreadyProbing);
            }
            s.probing = true;
            Ok(())
        })?;
        let _guard = ProbeGuard {
            state: self.state.clone(),
        };

        let rtt_ms = tokio::select! {
            res = ping_upstream(&self.config.upstream) => res.map_err(ProbeError::Failed)?,
            () = tokio::time::sleep(self.config.timeout) => return Err(ProbeError::TimedOut),
        };

        self.state.with(|s| {
            s.succeeded += 1;
            s.last_rtt_ms = rtt_ms;
        });
        Ok(rtt_ms)
    }
}

use crate::coordinator::{TransferCoordinator, TransferPermit};
use adamantium::{Bytes, Str};

#[derive(Clone, Debug)]
pub struct MoverConfig {
    pub region: Str,
    pub max_chunk_bytes: usize,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum MoverError {
    ChunkTooLarge { len: usize, max: usize },
    Coordinator(Str),
    StreamFailed(Str),
}

pub struct PartitionMover {
    config: MoverConfig,
    coordinator: TransferCoordinator,
}

impl PartitionMover {
    pub fn new(config: MoverConfig, coordinator: TransferCoordinator) -> Self {
        Self {
            config,
            coordinator,
        }
    }

    pub fn region(&self) -> &Str {
        &self.config.region
    }

    pub fn validate_chunk(&self, chunk: &Bytes) -> Result<(), MoverError> {
        if chunk.len() > self.config.max_chunk_bytes {
            return Err(MoverError::ChunkTooLarge {
                len: chunk.len(),
                max: self.config.max_chunk_bytes,
            });
        }
        Ok(())
    }

    pub async fn move_partition(&self, partition_id: u64, chunk: Bytes) -> Result<u64, MoverError> {
        self.validate_chunk(&chunk)?;
        let permit: TransferPermit = self
            .coordinator
            .mark_transfer_active(partition_id)
            .map_err(MoverError::Coordinator)?;

        let bytes_sent = stream_partition_chunk(&self.config.region, partition_id, &chunk)
            .await
            .map_err(MoverError::StreamFailed)?;

        self.coordinator
            .complete_transfer(permit)
            .map_err(MoverError::Coordinator)?;
        Ok(bytes_sent)
    }
}

use crate::journal::{JournalClient, StageHandle};
use adamantium::{Bytes, Str};

#[derive(Clone, Debug)]
pub struct ReplicatorConfig {
    pub cluster_id: Str,
    pub quorum_size: usize,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ReplicatorError {
    EmptyRecord,
    Journal(Str),
    QuorumFailed(Str),
}

pub struct WalReplicator {
    config: ReplicatorConfig,
    journal: JournalClient,
}

impl WalReplicator {
    pub fn new(config: ReplicatorConfig, journal: JournalClient) -> Self {
        Self { config, journal }
    }

    pub fn cluster_id(&self) -> &Str {
        &self.config.cluster_id
    }

    pub fn quorum_size(&self) -> usize {
        self.config.quorum_size
    }

    pub async fn append_replicated(
        &self,
        stream_id: u64,
        payload: Bytes,
    ) -> Result<u64, ReplicatorError> {
        if payload.is_empty() {
            return Err(ReplicatorError::EmptyRecord);
        }

        let handle: StageHandle = self
            .journal
            .begin_staged_write(stream_id, &payload)
            .map_err(ReplicatorError::Journal)?;

        let lsn = handle.provisional_lsn();
        replicate_to_quorum(
            &self.config.cluster_id,
            self.config.quorum_size,
            lsn,
            &payload,
        )
        .await
        .map_err(ReplicatorError::QuorumFailed)?;

        self.journal
            .finalize_staged_write(handle)
            .map_err(ReplicatorError::Journal)?;
        Ok(lsn)
    }
}
